// AUTO-GENERATED question banks for the Physiology 2nd Test CBT (src/pages/academics/Physio2CBT.tsx).
// Shape: { id, s (section), t (topic), q, o (options A-E), a (correct index), e (explanation) }

export interface P2Question { id: number; s: number; t: string; q: string; o: string[]; a: number; e: string }

// PART 1 - PAST QUESTIONS (253 questions: GIT, Cardiovascular, Renal)
export const PAST_Q: P2Question[] = [
{"id":1,"s":1,"t":"Gastrointestinal Physiology","q":"All the following statements are false except:","o":["The submucosal plexus controls mainly GIT secretions and local blood flow","The myenteric plexus mainly controls GIT secretions","The submucosal plexus is also known as Auerbach's plexus","Parasympathetic stimulation generally inhibits GIT motility","Sympathetic stimulation generally increases GIT blood flow"],"a":0,"e":"The submucosal (Meissner's) plexus primarily controls local gastrointestinal secretion, absorption, and submucosal blood flow, whereas the myenteric (Auerbach's) plexus controls gut motility."},
{"id":2,"s":1,"t":"Gastrointestinal Physiology","q":"Regulation of Secretion by the Brunner's gland is mainly:","o":["Sympathetic","Parasympathetic","Somatic","Enteric only","Hormonal only"],"a":1,"e":"Secretion of alkaline mucus by Brunner's glands in the duodenum is excited mainly by tactile or irritating stimuli, vagal (parasympathetic) stimulation, and gastrointestinal hormones such as secretin."},
{"id":3,"s":1,"t":"Gastrointestinal Physiology","q":"Which of the following is a member of the gastrin family of GIT hormones:","o":["Secretin","GIP","Motilin","Cholecystokinin","VIP"],"a":3,"e":"Cholecystokinin (CCK) and gastrin share the same C-terminal pentapeptide amino acid sequence, categorizing them into the same hormone family."},
{"id":4,"s":1,"t":"Gastrointestinal Physiology","q":"The blood supply and GIT secretion is mainly controlled by:","o":["Myenteric Plexus","Submucosal Plexus","Vagus nerve directly","Sympathetic chain","Auerbach's Plexus"],"a":1,"e":"The submucosal (Meissner's) plexus lies within the submucosa and regulates local glandular secretions, epithelial transport, and local blood flow."},
{"id":5,"s":1,"t":"Gastrointestinal Physiology","q":"The following are neurotransmitters secreted by enteric neurons except:","o":["Adrenaline","Acetylcholine","VIP","Substance P","Serotonin"],"a":0,"e":"Enteric neurons secrete acetylcholine, VIP, substance P, CCK, dopamine, and serotonin. Sympathetic postganglionic fibers release noradrenaline, whereas adrenaline is released into the blood by the adrenal medulla."},
{"id":6,"s":1,"t":"Gastrointestinal Physiology","q":"The sacral parasympathetic nerves of the spinal cord originate from:","o":["S1-S3","S2-S4","L1-L3","T12-L2","C5-C7"],"a":1,"e":"Sacral parasympathetic preganglionic outflow originates from the S2, S3, and S4 spinal cord segments to innervate the distal colon, rectum, bladder, and reproductive organs."},
{"id":7,"s":1,"t":"Gastrointestinal Physiology","q":"Hormones that act at site of production are referred to as:","o":["Endocrine","Autocrine","Paracrine","Neurocrine","Exocrine"],"a":2,"e":"Paracrine signaling involves chemical messengers secreted by cells into the interstitial fluid that act locally on neighboring target cells."},
{"id":8,"s":1,"t":"Gastrointestinal Physiology","q":"Which of the following is not a digestive juice:","o":["Saliva","Gastric juice","Pancreatic juice","Bile Juice","Succus entericus"],"a":3,"e":"Unlike salivary, gastric, pancreatic, and succus entericus (intestinal) juices, bile contains bile salts, bilirubin, and cholesterol, but no digestive enzymes."},
{"id":9,"s":1,"t":"Gastrointestinal Physiology","q":"The sublingual gland drains through:","o":["Stensen's Duct","Wharton's Duct","Rivinus Duct","Wirsung's Duct","Santorini's Duct"],"a":2,"e":"The sublingual salivary gland drains via multiple minor ducts known as the ducts of Rivinus (and the major sublingual duct of Bartholin). Stensen's duct drains the parotid, and Wharton's duct drains the submandibular gland."},
{"id":10,"s":1,"t":"Gastrointestinal Physiology","q":"Which of these salivary enzymes helps in the destruction of bacteria?","o":["Amylase","Lipase","Lysozyme","Mucin","Ptyalin"],"a":2,"e":"Salivary lysozyme and thiocyanate ions act as antibacterial agents that destroy bacterial cell walls and prevent oral infections."},
{"id":11,"s":1,"t":"Gastrointestinal Physiology","q":"Concerning mastication the following are correct except:","o":["Reflexive jaw drop/inhibition occurs when food touches the mouth","Breaks food into swallowable boluses","Breaks down cellulose walls of plant foods","Prevents mechanical mucosal excoriation","None of the above"],"a":4,"e":"Mastication involves reflexive jaw drop/inhibition when food touches the mouth, breaks food into swallowable boluses, breaks down cellulose walls of plant foods, and prevents mechanical mucosal excoriation."},
{"id":12,"s":1,"t":"Gastrointestinal Physiology","q":"Which of the following is not a fragment of CCK production:","o":["CCK 58","CCK 39","CCK 48","CCK 33","CCK 8"],"a":2,"e":"Naturally occurring active molecular forms of CCK produced from preprocholecystokinin include CCK-58, CCK-39, CCK-33, and CCK-8."},
{"id":13,"s":1,"t":"Gastrointestinal Physiology","q":"CCK secretion is controlled by:","o":["Negative Feedback","Positive Feedback","Feedforward control","Neural override exclusively","None of the above"],"a":0,"e":"Digestive products (fatty acids and peptides) stimulate duodenal I cells to release CCK; as digestion and gastric emptying proceed, reduced luminal nutrients decrease CCK release via negative feedback."},
{"id":14,"s":1,"t":"Gastrointestinal Physiology","q":"Which of the following is a function of Intrinsic factor:","o":["Helps in protein digestion","Protects the stomach lining","Activates pepsinogen","Helps in the absorption of iron","Helps in the absorption of Vitamin B12"],"a":4,"e":"Intrinsic factor, secreted by gastric parietal cells, binds dietary cyanocobalamin (Vitamin B12) to enable its receptor-mediated absorption in the terminal ileum."},
{"id":15,"s":1,"t":"Gastrointestinal Physiology","q":"Peptic Ulcer Disease is more common in Blood Group:","o":["Blood group A","Blood group B","Blood group AB","Blood group O","None of the above"],"a":3,"e":"Individuals with blood group O have a higher clinical incidence of duodenal peptic ulcer disease compared to other ABO blood groups."},
{"id":16,"s":1,"t":"Gastrointestinal Physiology","q":"Peptic ulcer can be treated by one of the following EXCEPT:","o":["NSAIDS","Proton Pump Inhibitors (PPIs)","Antacids","H2-receptor antagonists","Bismuth compounds"],"a":0,"e":"Non-steroidal anti-inflammatory drugs (NSAIDs) break down the gastric mucosal barrier and cause peptic ulcers, whereas PPIs (omeprazole, rabeprazole), antacids, and H2-receptor antagonists (ranitidine) treat peptic ulcers."},
{"id":17,"s":1,"t":"Gastrointestinal Physiology","q":"The Exocrine part of the pancreas secretes:","o":["Pancreatic Juice","Insulin","Glucagon","Somatostatin","Pancreatic polypeptide"],"a":0,"e":"Pancreatic acinar and ductal cells form the exocrine portion that secretes digestive enzyme-rich alkaline pancreatic juice, whereas islets of Langerhans form the endocrine portion (insulin, glucagon, somatostatin)."},
{"id":18,"s":1,"t":"Gastrointestinal Physiology","q":"Trypsinogen is converted to trypsin by:","o":["Enterokinase","Pepsin","HCl","Chymotrypsin","Amylase"],"a":0,"e":"Enterokinase (enteropeptidase) on the duodenal mucosal brush border cleaves inactive trypsinogen to active trypsin."},
{"id":19,"s":1,"t":"Gastrointestinal Physiology","q":"The preganglionic Parasympathetic nerves to the oesophagus pass through:","o":["CN V","CN VII","CN IX","CN XI","CN X"],"a":4,"e":"Parasympathetic innervation to the pharynx, esophagus, stomach, and foregut/midgut organs is supplied by preganglionic fibers of the Vagus nerve (Cranial Nerve X)."},
{"id":20,"s":1,"t":"Gastrointestinal Physiology","q":"Which of the Following would cause Conjugated Hyperbilirubinemia:","o":["ABO incompatibility","Erythroblastosis fetalis","Sickle cell anemia","Excessive hemolysis","None of the Above"],"a":4,"e":"ABO incompatibility, erythroblastosis fetalis, and sickle cell anemia cause hemolysis, resulting in unconjugated (indirect) hyperbilirubinemia. Conjugated hyperbilirubinemia is caused by post-hepatic biliary obstruction."},
{"id":21,"s":2,"t":"Cardiovascular Physiology","q":"The circle of Willis which is the main blood supply to the brain is MAINLY formed by:","o":["Terminal branches of the internal carotid artery and basilar arteries","External carotid artery and vertebral arteries","Middle cerebral artery and jugular veins","Anterior cerebral artery and subclavian artery","Ophthalmic artery and basilar artery"],"a":0,"e":"The arterial circle of Willis at the base of the brain is formed by anastomoses between the internal carotid arteries and the basilar artery (derived from vertebral arteries)."},
{"id":22,"s":2,"t":"Cardiovascular Physiology","q":"The following are risk factors for coronary artery disease except:","o":["Sedentary lifestyle","Cigarette smoking","Obesity","Inter ventricular septum","Hypertension"],"a":3,"e":"Sedentary lifestyle, cigarette smoking, family history, obesity, hypercholesterolemia, and hypertension are major coronary artery disease risk factors; the interventricular septum is normal cardiac anatomy."},
{"id":23,"s":2,"t":"Cardiovascular Physiology","q":"The vessel that serves as the main source of oxygenated blood to the fetus is:","o":["Umbilical artery","Umbilical vein","Ductus venosus","Ductus arteriosus","Foramen ovale"],"a":1,"e":"Oxygenated, nutrient-rich blood flows from the placenta to the fetal circulation via the single umbilical vein (oxygen saturation ~70-80%)."},
{"id":24,"s":2,"t":"Cardiovascular Physiology","q":"The difference between systolic and diastolic blood pressure is known as:","o":["Pulse pressure","Mean arterial pressure","Stroke volume","Cardiac output","Peripheral resistance"],"a":0,"e":"Pulse pressure is calculated as Systolic Blood Pressure minus Diastolic Blood Pressure (PP = SBP - DBP)."},
{"id":25,"s":2,"t":"Cardiovascular Physiology","q":"Baroreceptor reflexes are classified under which of the following groups of arterial blood pressure regulation?","o":["Short term nervous","Long term hormonal","Intermediate fluid shift","Long term renal","Short term hormonal"],"a":0,"e":"Arterial baroreceptor reflexes respond within seconds to acute pressure fluctuations via autonomic nerves, providing rapid short-term BP control."},
{"id":26,"s":2,"t":"Cardiovascular Physiology","q":"The following are directly involved in blood pressure regulation except:","o":["Angiotensin I","Angiotensin II","ANP","Cortisol","Aldosterone"],"a":3,"e":"Angiotensin I, Angiotensin II, ANP, and Aldosterone directly regulate vascular tone, ECF volume, and renal sodium balance; cortisol is a glucocorticoid regulating metabolic stress responses."},
{"id":27,"s":2,"t":"Cardiovascular Physiology","q":"The functions of Angiotensin II include the following except:","o":["Vasoconstriction that reduces total peripheral resistance","Direct arteriolar vasoconstriction","Stimulates aldosterone release","Stimulates ADH release","Triggers thirst"],"a":0,"e":"Angiotensin II is a potent direct arteriolar vasoconstrictor that increases total peripheral resistance (TPR), stimulates aldosterone and ADH release, and triggers thirst."},
{"id":28,"s":2,"t":"Cardiovascular Physiology","q":"The hormone Aldosterone is secreted by:","o":["Adrenal medulla","Kidney","Adrenal cortex","Anterior pituitary","Hypothalamus"],"a":2,"e":"Aldosterone is synthesized and secreted by the zona glomerulosa of the adrenal cortex."},
{"id":29,"s":2,"t":"Cardiovascular Physiology","q":"The heart chamber tasked with receiving oxygenated blood from the lungs is the:","o":["Right atrium","Left atrium","Left ventricle","Right ventricle","Pulmonary trunk"],"a":1,"e":"Oxygenated blood returns from the pulmonary circulation via four pulmonary veins into the left atrium."},
{"id":30,"s":2,"t":"Cardiovascular Physiology","q":"The innermost layer of the blood vessel is which of the following?","o":["Tunica Media","Tunica Adventitia","Tunica Intima","Internal elastic lamina","Endocardium"],"a":2,"e":"The tunica intima consists of a single layer of vascular endothelial cells lining the luminal surface of blood vessels."},
{"id":31,"s":2,"t":"Cardiovascular Physiology","q":"The blood vessel layer mostly involved in vasoconstriction and dilatation is the:","o":["Tunica Intima","Tunica Adventitia","Endothelium","Tunica media","Vasa vasorum"],"a":3,"e":"The tunica media contains vascular smooth muscle fibers that contract or relax to alter vessel diameter and resistance."},
{"id":32,"s":2,"t":"Cardiovascular Physiology","q":"Which of the following blood vessel layer is present in a capillary?","o":["Tunica media","Tunica adventitia","Tunica intima","External elastic lamina","Submucosa"],"a":2,"e":"True capillaries consist solely of an endothelial cell layer (tunica intima) resting on a basement membrane."},
{"id":33,"s":2,"t":"Cardiovascular Physiology","q":"The force per unit area exerted on a vessel by contained blood is referred to as:","o":["Blood pressure","Vascular resistance","Cardiac output","Stroke volume","Venous return"],"a":0,"e":"Arterial blood pressure is defined as the lateral force per unit area exerted by moving blood against the blood vessel walls."},
{"id":34,"s":2,"t":"Cardiovascular Physiology","q":"Which of these are true about hypertension?","o":["Secondary hypertension is the most common type","Essential hypertension can also be referred to as idiopathic","It is usually caused by a single known factor","It leads to decreased peripheral resistance","It only affects the elderly"],"a":1,"e":"Essential (primary) hypertension accounts for ~90-95% of cases and is termed idiopathic because its underlying cause is multi-factorial."},
{"id":35,"s":2,"t":"Cardiovascular Physiology","q":"The neural center that controls the change in blood vessel diameters is the:","o":["Vasomotor center","Respiratory center","Apneustic center","Pneumotaxic center","Cardiac accelerator center"],"a":0,"e":"The vasomotor center located bilaterally in the reticular formation of the medulla oblongata and lower pons controls vascular tone and vessel diameter."},
{"id":36,"s":2,"t":"Cardiovascular Physiology","q":"Atrial depolarization is represented by which of the following on an ECG tracing?","o":["QRS complex","T wave","P wave","U wave","PR interval"],"a":2,"e":"The P wave represents electrical depolarization spreading across both the right and left atria."},
{"id":37,"s":2,"t":"Cardiovascular Physiology","q":"QRS complex signifies which of the following?","o":["Atrial depolarization","Ventricular depolarization","Ventricular repolarization","Atrial repolarization","Purkinje fiber repolarization"],"a":1,"e":"The QRS complex represents rapid electrical depolarization of the right and left ventricles prior to contraction."},
{"id":38,"s":2,"t":"Cardiovascular Physiology","q":"A variant of circulatory shock in which there is an increase in the vascular capacity is known as:","o":["Vasogenic shock","Distributive shock","Hypovolemic shock","Cardiogenic shock","A and B"],"a":4,"e":"Distributive (vasogenic) shock—including neurogenic, anaphylactic, and septic shock—is characterized by widespread loss of vascular tone and pathologically increased vascular capacity."},
{"id":39,"s":2,"t":"Cardiovascular Physiology","q":"About systolic heart failure:","o":["There is an inability of the heart to relax","There is a decrease in the ability of the heart to contract","Ejection fraction is usually normal or increased","It is caused by increased compliance of the ventricles","It is synonymous with right heart failure"],"a":1,"e":"Systolic heart failure features impaired myocardial contractility, leading to reduced stroke volume and a decreased ejection fraction (<40-50%)."},
{"id":40,"s":2,"t":"Cardiovascular Physiology","q":"Which of the following is an INCORRECT sequence of electrical activity transmission?","o":["SA node to AV node","AV node to Bundle of His","Bundle of His to Bundle Branches","Purkinje fibres to AV node","Bundle Branches to Purkinje fibers"],"a":3,"e":"Electrical impulses travel sequentially from SA node -> AV node -> Bundle of His -> Right and Left Bundle Branches -> Purkinje fibers -> Ventricular myocardium."},
{"id":41,"s":3,"t":"Renal Physiology","q":"Which of the following is not a property of marker substances?","o":["It must not remain in the compartment being measured","It must distribute evenly","It must not be toxic","It must not alter the volume of the compartment","It must be easy to measure"],"a":0,"e":"An ideal indicator/marker substance for volume measurement must distribute evenly and remain within the specific fluid compartment being measured."},
{"id":42,"s":3,"t":"Renal Physiology","q":"One of the following factors does not influence capillary hydrostatic pressure:","o":["Arterial pressure","Venous pressure","Arteriolar resistance","Capillary osmotic coefficient","Venular resistance"],"a":3,"e":"Capillary hydrostatic pressure (Pc) is influenced by arterial pressure, venous pressure, and arteriolar/venular resistances, whereas osmotic and reflection coefficients govern oncotic driving forces and membrane flux."},
{"id":43,"s":3,"t":"Renal Physiology","q":"Concerning the functional histology of the kidney:","o":["Superficial cortical nephrons have short loops of Henle","Juxtamedullary nephrons have long loops dipping deep into the medulla","Medullary blood flow shifts during dehydration","All of the above","None of the above"],"a":3,"e":"Superficial cortical nephrons have short loops of Henle with lower salt-concentrating capacity; juxtamedullary nephrons have long loops dipping deep into the medulla with high reabsorptive capacity; medullary blood flow shifts during dehydration."},
{"id":44,"s":3,"t":"Renal Physiology","q":"These are all functions of the kidney except:","o":["Homeostasis","Regulation of urea-base balance","Acid-base balance regulation","Blood pressure control","Gluconeogenesis"],"a":1,"e":"Major kidney functions include homeostasis, acid-base balance regulation, blood pressure control, gluconeogenesis, waste excretion, and endocrine secretion."},
{"id":45,"s":3,"t":"Renal Physiology","q":"Concerning the nephron:","o":["Only the right kidney has exactly 1.3 million nephrons","New nephrons are continuously formed throughout life","Both kidneys have a total of approximately 1.3million nephrons","They are completely absent in the renal medulla","Their numbers drastically increase during dehydration"],"a":2,"e":"Each human kidney contains approximately 1.0 to 1.3 million nephrons, giving a total of ~2.0 to 2.6 million per individual. No new nephrons develop after birth."},
{"id":46,"s":3,"t":"Renal Physiology","q":"Concerning the loop of Henle:","o":["The thick ascending limb is highly permeable to water","The thin limb consists of flattened epithelial cells","The descending limb actively pumps sodium","The loop of Henle is found exclusively in the cortex","It lacks a hairpin turn"],"a":1,"e":"The thin descending and thin ascending limbs of Henle's loop are lined with simple, thin, flattened squamous epithelial cells with minimal metabolic machinery."},
{"id":47,"s":3,"t":"Renal Physiology","q":"In the regulation of renal blood flow:","o":["Sympathetic stimulation exclusively dilates afferent arterioles","Nitric oxide causes profound vasoconstriction","Prostaglandins act mainly in efferent arterioles","Angiotensin II acts mainly in efferent arterioles","Autoregulation fails completely below 100 mmHg"],"a":3,"e":"Angiotensin II preferentially constricts efferent renal arterioles, maintaining glomerular hydrostatic pressure and GFR during reduced renal perfusion."},
{"id":48,"s":3,"t":"Renal Physiology","q":"Which of these is NOT a factor affecting GFR:","o":["Filtration surface area","Capillary permeability","Constriction of afferent venules","Net filtration pressure","Afferent/efferent arteriolar resistance"],"a":2,"e":"GFR is affected by filtration surface area, capillary permeability, net filtration pressure, and afferent/efferent arteriolar resistance. The renal microcirculation lacks 'afferent venules'."},
{"id":49,"s":3,"t":"Renal Physiology","q":"The following are factors that will decrease GFR EXCEPT:","o":["Constriction of afferent arterioles","Dilation of efferent arterioles","Dilation of afferent arterioles","Increased Bowman's capsule hydrostatic pressure","Increased plasma colloid osmotic pressure"],"a":2,"e":"Dilating afferent arterioles increases glomerular capillary hydrostatic pressure and renal blood flow, which increases GFR."},
{"id":50,"s":3,"t":"Renal Physiology","q":"Majority of the Ca2+ is actively reabsorbed in PCT through the action of:","o":["Ca2+ channels","Na+/K+ pump","Ca2+ ATPase","K+ ATPase","Simple diffusion"],"a":2,"e":"Passive paracelluar reabsorption accounts for most PCT calcium uptake, while basolateral active exit occurs via primary Ca2+-ATPase pumps and Na+/Ca2+ antiporters."},
{"id":51,"s":3,"t":"Renal Physiology","q":"The renal threshold for glucose in normal individuals is:","o":["50mg/dl","100mg/dl","150mg/dl","200mg/dl","300mg/dl"],"a":3,"e":"Glucose begins to appear in the urine (renal threshold) when venous plasma glucose levels exceed approximately 180 to 200 mg/dL (10 mmol/L)."},
{"id":52,"s":3,"t":"Renal Physiology","q":"Glucose reabsorption occurs in the:","o":["Proximal tubule.","Loop of Henle.","Distal convoluted tubule.","Collecting duct.","Bowman's capsule."],"a":0,"e":"Filtered glucose is virtually 100% reabsorbed in the early and late segments of the proximal convoluted tubule via SGLT2 and SGLT1 cotransporters."},
{"id":53,"s":3,"t":"Renal Physiology","q":"Which one of the following is the major mechanism defending ECF volume?","o":["Potassium balance","Sodium balance","Calcium balance","Phosphate balance","Magnesium balance"],"a":1,"e":"Sodium is the principal extracellular cation; because water follows sodium passively by osmosis, long-term ECF volume control relies on renal sodium balance."},
{"id":54,"s":3,"t":"Renal Physiology","q":"The following are steps in the countercurrent multiplier mechanism EXCEPT:","o":["Single effects (active solute transport)","Axial fluid shifts","Osmotic equilibration","Wash-out step","All of the above are steps"],"a":3,"e":"The countercurrent multiplier operates through single effects (active solute transport), axial fluid shifts, and osmotic equilibration to build medullary hypertonicity. Excessive medullary blood flow causes 'wash-out', which dissipates the gradient."},
{"id":55,"s":3,"t":"Renal Physiology","q":"To produce concentrated urine, there is need for:","o":["Low concentration of ADH","Isotonic medullary interstitium","High concentration of ADH","High fluid intake","Inhibition of the countercurrent multiplier"],"a":2,"e":"Excreting concentrated urine requires elevated circulating ADH (to render collecting ducts permeable to water) and a hypertonic medullary interstitium."},
{"id":56,"s":3,"t":"Renal Physiology","q":"Excretion of H+ occurs by the following mechanisms EXCEPT:","o":["Glucose mechanism","Free H+ secretion","Titration of filtered phosphate buffers","Ammonium (NH4+) trapping","None of the above"],"a":0,"e":"Renal hydrogen ion excretion and new bicarbonate generation occur via free H+ secretion, titration of filtered phosphate buffers, and ammonium (NH4+) trapping."},
{"id":57,"s":3,"t":"Renal Physiology","q":"Renal acid secretion is altered by changes in the following EXCEPT:","o":["Intracellular PCO2","Carbonic anhydrase activity","Plasma potassium","ADH levels","Adrenocortical mineralocorticoids (aldosterone)"],"a":3,"e":"Renal H+ secretion is modulated by intracellular PCO2, carbonic anhydrase activity, plasma potassium, and adrenocortical mineralocorticoids (aldosterone), whereas ADH regulates water permeability."},
{"id":58,"s":3,"t":"Renal Physiology","q":"Ammonia is an effective urinary buffer for which of the following reasons:","o":["It has a very low pKa","The walls of the renal tubules are impermeable to NH4+","It is actively transported back into the blood","It decreases the pH of urine dramatically","It is a large protein"],"a":1,"e":"Non-ionic NH3 diffuses freely into the tubular lumen where it combines with secreted H+ to form NH4+; the luminal membrane is impermeable to NH4+, trapping it for excretion."},
{"id":59,"s":3,"t":"Renal Physiology","q":"Concerning micturition, the first urge to void is felt at a bladder volume of about:","o":["50 mL","150 mL","300 mL","500 mL","1000 mL"],"a":1,"e":"The initial sensory urge to void is felt at a bladder volume of ~150 mL, with a marked sense of fullness developing at ~300 to 400 mL."},
{"id":60,"s":3,"t":"Renal Physiology","q":"Which one of the following hormones is not secreted in a state of dehydration?","o":["Atrial natriuretic peptide","Vasopressin (ADH)","Angiotensin II","Aldosterone","Renin"],"a":0,"e":"Dehydration reduces ECF and blood volume, which inhibits ANP release. Vasopressin (ADH), Angiotensin II, and Aldosterone are elevated to conserve fluid."},
{"id":61,"s":2,"t":"Cardiovascular Physiology","q":"Maximum peripheral resistance is offered at which region of the body:","o":["Splanchnic region","Respiratory region","Neuro-muscular region","Spinal region","Caudal region"],"a":0,"e":"The splanchnic circulation represents the largest systemic regional vascular bed and receives approximately 25% of cardiac output at rest, contributing the greatest overall proportion to total peripheral vascular resistance."},
{"id":62,"s":2,"t":"Cardiovascular Physiology","q":"Vasodilator area is also situated in the reticular formation of medulla oblongata in the floor of which ventricle:","o":["VI","V","IV","III","VII"],"a":2,"e":"The vasomotor center (including the depressor/vasodilator area) is located in the reticular formation of the medulla oblongata and lower pons, situated in the floor of the fourth ventricle."},
{"id":63,"s":2,"t":"Cardiovascular Physiology","q":"Which portion of the vasomotor center does the depressor area form?","o":["Ventral portion","Medial portion","Posterior portion","Lateral portion","Longitudinal portion"],"a":1,"e":"The depressor (vasodilator) area of the medullary vasomotor center occupies the ventromedial portion of the lower medulla, inhibiting the anterolateral vasoconstrictor area."},
{"id":64,"s":2,"t":"Cardiovascular Physiology","q":"The amount of blood pumped by the left ventricle of the heart in one contraction is:","o":["Vena cava center","Cardiac output","Stroke volume","Depressor volume","Vasomotor center"],"a":2,"e":"Stroke Volume (SV) is defined as the volume of blood ejected by each ventricle during a single cardiac contraction (SV = EDV - ESV)."},
{"id":65,"s":2,"t":"Cardiovascular Physiology","q":"The following is not a part of the specialized conduction system of the heart:","o":["The Purkinje fibers","The SA node","The Bundle of His","The AV node","Voltage gated sodium channels"],"a":4,"e":"The specialized cardiac conducting system consists of histological tissues: the SA node, internodal tracts, AV node, Bundle of His, bundle branches, and Purkinje fibers. Voltage-gated channels are membrane proteins, not structural components."},
{"id":66,"s":2,"t":"Cardiovascular Physiology","q":"The following are seen in the ventricular action potential except:","o":["Plateau phase","Rapid depolarization with overshoot","Initial rapid repolarization","Prepotential","Rapid repolarization"],"a":3,"e":"Prepotentials (pacemaker potentials) occur exclusively in autorhythmic nodal cells (SA/AV nodes). Working ventricular myocytes have a stable resting membrane potential (-90 mV) followed by phases 0 to 4."},
{"id":67,"s":2,"t":"Cardiovascular Physiology","q":"Vasogenic shock can occur because of:","o":["Cardiac failure","Vomiting and diarrhoea","Severe burns","Incompatible blood transfusion","Osmotic diuresis"],"a":3,"e":"Incompatible blood transfusion triggers severe immune-mediated antigen-antibody reactions and massive histamine release, leading to widespread vasodilation (vasogenic/anaphylactic shock). Vomiting, diarrhea, and severe burns cause hypovolemic shock."},
{"id":68,"s":2,"t":"Cardiovascular Physiology","q":"In hypovolemic shock the fall in arterial blood pressure causes the following except:","o":["Tachycardia","Redistribution of blood flow to favour the heart and brain","Reduced blood flow to skin and kidneys","Increased release of catecholamines from adrenal medulla","Pedal edema"],"a":4,"e":"Hypovolemic shock features severe depletion of blood and ECF volume, causing hypotension, compensatory tachycardia, cutaneous/renal vasoconstriction, and catecholamine release. Peripheral pedal edema occurs in volume overload or heart failure, not volume depletion."},
{"id":69,"s":2,"t":"Cardiovascular Physiology","q":"Irreversible shock is characterized by:","o":["Depression of myocardium and vasomotor center","Increased capillary permeability","Release of toxins from gram negative bacteria","Generalized cellular deterioration","All the above"],"a":4,"e":"Irreversible circulatory shock is characterized by myocardial and vasomotor center depression, increased capillary permeability, toxin release, and progressive, multi-organ cellular deterioration."},
{"id":70,"s":2,"t":"Cardiovascular Physiology","q":"Heart sounds are produced by the following except:","o":["Flow of blood through cardiac chambers","Contraction of cardiac muscle","Opening of valves of the heart","Mechanical activities of the heart","Closure of valves of the heart"],"a":2,"e":"Opening of healthy heart valves occurs smoothly and is completely silent; heart sounds result from valve closure, blood turbulence, and vascular vibrations."},
{"id":71,"s":2,"t":"Cardiovascular Physiology","q":"Incompetence of Atrioventricular valves in systolic murmur:","o":["It causes regurgitation of blood from the atria into the ventricles during systole","It reduces the viscosity and flow of blood generally","It is a congenital disorder","It causes regurgitation of blood from the ventricles into the atria during systole","The left ventricular pressure raises up to 300mmHg during systole"],"a":3,"e":"Incompetence (regurgitation) of the AV valves (mitral or tricuspid) allows blood to flow backward from the high-pressure ventricles into the low-pressure atria during ventricular systole, producing a pansystolic murmur."},
{"id":72,"s":2,"t":"Cardiovascular Physiology","q":"Which of these cannot be detected by the electrocardiogram?","o":["Rate of the heart","Rhythm of the heart","Presence of asymptomatic blockages in the atria of the heart","State of the conducting tissues in the myocardium","Origin and rate of cardiac excitation"],"a":2,"e":"An ECG records electrical voltage waves over time (heart rate, rhythm, electrical conduction blocks, chamber hypertrophy) but cannot directly visualize non-electrical anatomical blockages or structural tissue defects that do not alter electrical vectors."},
{"id":73,"s":2,"t":"Cardiovascular Physiology","q":"Counting the number of QRS complexes, which of the following can be interpreted?","o":["Cardiac output","Venous return","Stroke volume","Rate of heartbeat","Rate of breathing"],"a":3,"e":"Each QRS complex represents one ventricular depolarization and contraction cycle; counting QRS complexes per unit time determines the ventricular heart rate."},
{"id":74,"s":2,"t":"Cardiovascular Physiology","q":"A normal PR interval duration ranges between:","o":["0.12-0.20 seconds","0.04-0.08 seconds","0.08-0.12 seconds","0.04-0.12 seconds","0.05-0.10 seconds"],"a":0,"e":"The normal PR interval (from the onset of the P wave to the beginning of the QRS complex) lasts between 0.12 and 0.20 seconds."},
{"id":75,"s":2,"t":"Cardiovascular Physiology","q":"PR interval with a duration greater than 0.2 seconds denotes block in the conduction of impulses in:","o":["the SA node","the Purkinje fibers","between the atrium and the ventricles","the bundle of His","the AV node"],"a":4,"e":"A PR interval exceeding 0.20 seconds indicates a first-degree heart block caused by delayed conduction through the AV node."},
{"id":76,"s":2,"t":"Cardiovascular Physiology","q":"Distribution vessels include the following except:","o":["Radial artery","Axillary artery","Ulnar artery","Popliteal artery","Femoral artery"],"a":1,"e":"The axillary artery is classified as a large elastic (conducting) artery, whereas medium-sized muscular arteries (radial, ulnar, popliteal, femoral) are distributing vessels that control blood delivery to regional tissue beds."},
{"id":77,"s":2,"t":"Cardiovascular Physiology","q":"Which of the following parts of the blood vessel wall lies in contact with the blood?","o":["Basal lamina","Endothelium","Subendothelial connective tissue","Internal elastic lamina","External elastic lamina"],"a":1,"e":"The endothelium is the single layer of specialized squamous epithelial cells lining the innermost surface of the tunica intima in direct contact with flowing blood."},
{"id":78,"s":2,"t":"Cardiovascular Physiology","q":"Which layer of the vessel wall prevents undue stretch of the blood vessel?","o":["Tunica intima","Tunica adventitia","Tunica media","Internal elastic lamina","External elastic lamina"],"a":1,"e":"The tunica adventitia (externa) consists of dense collagenous connective tissue that provides structural tensile strength and prevents overdistension and rupture of blood vessels under hydrostatic pressure."},
{"id":79,"s":2,"t":"Cardiovascular Physiology","q":"In the following conditions the blood pressure increases except:","o":["After meals","Exposure to cold","In the morning","Muscular exercise","Excitement"],"a":0,"e":"After meals, extensive splanchnic vasodilation causes significant pooling of blood in gastrointestinal vessels, which tends to reduce peripheral vascular resistance (often causing postprandial hypotension)."},
{"id":80,"s":2,"t":"Cardiovascular Physiology","q":"Which of the following is a short term blood pressure control mechanism?","o":["Chemoreceptor reflexes","Renin-angiotensin vasoconstrictor mechanism","Capillary fluid shift mechanism","Aldosterone system","Renal body fluid feedback mechanism"],"a":0,"e":"Arterial chemoreceptors and baroreceptors trigger rapid neural autonomic responses within seconds to control acute blood pressure fluctuations, providing short-term regulation."},
{"id":81,"s":1,"t":"Gastrointestinal Physiology","q":"Which of the following is true of gastrin?","o":["acts via the receptor CCK-b","inactivated in the small intestine only","decreased vagal discharge is a stimulant","its neurotransmitter is acetylcholine","it is not blocked by atropine"],"a":4,"e":"Vagal-induced gastrin secretion from antral G cells is mediated by Gastrin-Releasing Peptide (GRP/bombesin) at postganglionic terminals, making it resistant to atropine blockade."},
{"id":82,"s":1,"t":"Gastrointestinal Physiology","q":"The following functions of Cholecystokinin are true except:","o":["inhibits motility of the stomach, intestine and colon","augments contraction of pyloric sphincter","Induces drug tolerance to opoids","increases the secretion of enterokinase","augments the action of secretin in producing alkaline pancreatic juice"],"a":3,"e":"CCK contracts the gallbladder, relaxes the sphincter of Oddi, inhibits gastric emptying, and stimulates pancreatic enzyme secretion, but it does not stimulate enterokinase secretion."},
{"id":83,"s":1,"t":"Gastrointestinal Physiology","q":"The GI hormone which acts on the cells of pancreatic ductile via cyclic AMP is:","o":["Motilin","Vasoactive Intestinal Polypeptide","Secretin","GIP","Cholecystokinin"],"a":2,"e":"Secretin binds to G-protein coupled receptors on pancreatic ductal epithelial cells, elevating intracellular cAMP to stimulate sodium bicarbonate-rich fluid secretion."},
{"id":84,"s":1,"t":"Gastrointestinal Physiology","q":"Secretin and cholecystokinin are secreted in:","o":["Oesophagus","Ileum","Pyloric region","Duodenum","Stomach"],"a":3,"e":"Secretin (from S cells) and CCK (from I cells) are both produced and released by mucosal enteroendocrine cells in the duodenum and upper jejunum."},
{"id":85,"s":1,"t":"Gastrointestinal Physiology","q":"One of the following is released in response to acidic chyme in the duodenum:","o":["Gastrin","Secretin","Cholecystokinin","Peptide","Amylase"],"a":1,"e":"Acidic chyme (pH < 4.5) entering the duodenum triggers S cells to secrete secretin into the circulation."},
{"id":86,"s":1,"t":"Gastrointestinal Physiology","q":"Under normal conditions, the stomach can expand to accommodate........ liters of solids and liquids.","o":["1.5L","6.6L","7.5L","12.5L","7.5L"],"a":0,"e":"The normal resting human stomach undergoes receptive relaxation to comfortably store 1.0 to 1.5 liters of ingested food and liquid."},
{"id":87,"s":1,"t":"Gastrointestinal Physiology","q":"Which of these is referred to as the appetite center in the cephalic phase:","o":["Basal ganglia","Hypothalamus","Putman","Cerebrum","Epiglottis"],"a":1,"e":"The lateral hypothalamic area acts as the primary feeding/appetite center, integrating central sensory and cephalic inputs to regulate hunger."},
{"id":88,"s":1,"t":"Gastrointestinal Physiology","q":"Enterogastric reflex is mediated by:","o":["Myenteric nerve (Auerbach) plexus","Epigastrin","Pepsin","Pepsinogen","Sympathetic nervous system"],"a":0,"e":"The enterogastric reflex is initiated by acid, fat, and distension in the duodenum and travels via myenteric plexus short reflexes (as well as extrinsic sympathetic nerves) to slow gastric motility."},
{"id":89,"s":1,"t":"Gastrointestinal Physiology","q":"All of these can cause peptic ulcer except:","o":["Hyperalkalinity of gastric juice","Reduced alkalinity of duodenal content","Decreased mucin content in gastric juice","Constant physical or emotional stress","Food with excess spices or smoking"],"a":0,"e":"Peptic ulcer disease results from hyperacidity (excessive HCl and pepsin) breaking down mucosal barriers; hyperalkalinity neutralizes acid and protects against ulceration."},
{"id":90,"s":1,"t":"Gastrointestinal Physiology","q":"Which of the following results in the highest level of sweating:","o":["hot, dry days with cold nights","cool, dry days and nights","hot, dry days","wet, muddy, cool days","warm, dry average conditions"],"a":2,"e":"High environmental heat on dry days strongly activates hypothalamic thermoregulatory centers, driving maximal eccrine sweat production to facilitate evaporative cooling."},
{"id":91,"s":1,"t":"Gastrointestinal Physiology","q":"Which of the following hormones is incorrectly matched with the response it generates?","o":["CCK, inhibits intake via vagus nerve signaling to the brain","Ghrelin stimulates hunger by activating POMC and CART","Insulin signals satiety by inhibiting NPY/AgRP production","Leptin, suppresses appetite by binding to the OB-R receptor","All of the above are correctly matched"],"a":1,"e":"Ghrelin stimulates hunger by activating NPY/AgRP neurons in the arcuate nucleus. POMC/CART neurons release α-MSH to suppress appetite (anorexigenic)."},
{"id":92,"s":1,"t":"Gastrointestinal Physiology","q":"In Achalasia:","o":["It is a condition in which the lower esophageal sphincter fails to relax during swallowing","As a result, food swallowed into the esophagus then fails to pass from the esophagus into the stomach","There is damage in the neural network of the myenteric plexus in the Lower two thirds of the esophagus","All of the above","None of the above"],"a":3,"e":"Achalasia is characterized by failure of the lower esophageal sphincter to relax during swallowing, esophageal aperistalsis, and loss of myenteric plexus inhibitory postganglionic neurons in the distal esophagus."},
{"id":93,"s":1,"t":"Gastrointestinal Physiology","q":"Malabsorption can be caused by:","o":["Adequate digestion","Inadequate absorption","Adequate digestion and absorption","A and B","Adequate absorption"],"a":1,"e":"Malabsorption syndromes stem directly from mucosal epithelial defects, mucosal surface area reduction, or transport failures resulting in inadequate nutrient absorption."},
{"id":94,"s":1,"t":"Gastrointestinal Physiology","q":"Carbohydrates are present in the following forms in the diet except:","o":["amylopectin","glycogen","fructose","purine","sucrose"],"a":3,"e":"Purines are nitrogenous bases (found in nucleic acids like DNA and RNA), not dietary carbohydrates."},
{"id":95,"s":1,"t":"Gastrointestinal Physiology","q":"Which of these carbohydrates is present in germinating seeds?","o":["Cellulose","Galactose","Sucrose","Maltose","Lactose"],"a":3,"e":"Maltose (malt sugar) is a disaccharide produced in large amounts during seed germination through enzymatic breakdown of starch."},
{"id":96,"s":1,"t":"Gastrointestinal Physiology","q":"Pentoses are absorbed by:","o":["Simple diffusion","Facilitated diffusion","Primary active transport","Secondary active transport","Endocytosis"],"a":0,"e":"Five-carbon sugars (pentoses such as xylose and arabinose) pass across the intestinal mucosal brush border passively via simple diffusion."},
{"id":97,"s":1,"t":"Gastrointestinal Physiology","q":"Glucose is transported into the blood capillaries by:","o":["Glucose Transporter 5","Glucose Transporter 2","Sodium-Glucose Transporter 1","Sodium-Glucose Transporter 4","Simple diffusion"],"a":1,"e":"Glucose crosses the basolateral enterocyte membrane into the interstitial space and blood capillaries via facilitated diffusion mediated by GLUT2."},
{"id":98,"s":1,"t":"Gastrointestinal Physiology","q":"Pepsinogen is activated by:","o":["HCl","Bile","Lecithin","Trypsin","Enterokinase"],"a":0,"e":"Hydrochloric acid (HCl) secreted by parietal cells creates the acidic pH necessary to cleave inactive pepsinogen into active pepsin."},
{"id":99,"s":1,"t":"Gastrointestinal Physiology","q":"What is the term used to describe movement of substances through the gastrointestinal tract:","o":["Peristalsis","Segmentation","Chyme","Faeces","Mucus"],"a":0,"e":"Peristalsis is the universal propulsive movement that creates a progressive wave of contraction moving chyme caudally along the alimentary canal."},
{"id":100,"s":1,"t":"Gastrointestinal Physiology","q":"The following factors can affect gastrointestinal motility EXCEPT:","o":["Emotional state","Time of day","Physical activity","Sex","Type of food"],"a":3,"e":"Gastrointestinal motility is directly influenced by meal composition, autonomic/emotional state, physical activity, and circadian factors, whereas gender plays no direct primary regulatory role."},
{"id":101,"s":3,"t":"Renal Physiology","q":"Where are all of the glomeruli of the kidney located?","o":["in the medulla","in the columns","in the pyramids","in the cortex","in the pelvis"],"a":3,"e":"All renal glomeruli and Bowman's capsules are located strictly in the outer renal cortex (either superficial, mid-cortical, or juxtamedullary regions)."},
{"id":102,"s":3,"t":"Renal Physiology","q":"Which part of the nephron is impermeable to water?","o":["Proximal convoluted tubule","Distal convoluted tubule in the presence of ADH","Ascending limb of the loop of Henle","Descending limb of the loop of Henle","Bowman capsule"],"a":2,"e":"The ascending limb of the Loop of Henle (both thin and thick segments) is completely impermeable to water, allowing solute reabsorption to dilute tubular fluid."},
{"id":103,"s":3,"t":"Renal Physiology","q":"Glomerular filtration rate would be decreased by:","o":["dilatation of the afferent arteriole","an increase in afferent arteriolar resistance","a decrease in bowman capsular hydrostatic pressure","a decrease in the concentration of plasma protein","an increase in renal blood flow"],"a":1,"e":"Afferent arteriolar vasoconstriction (increased resistance) reduces downstream glomerular capillary hydrostatic pressure (Pgc), decreasing GFR."},
{"id":104,"s":3,"t":"Renal Physiology","q":"Normally, most of the titratable acidity of urine is attributable to acid buffered by:","o":["bicarbonate","phosphate","ammonia","lactate","A and B"],"a":1,"e":"Titratable acidity in urine represents secreted H+ buffered primarily by filtered inorganic phosphate (HPO4(2-) + H+ -> H2PO4-)."},
{"id":105,"s":3,"t":"Renal Physiology","q":"In humans, what percentage of nephrons has long loops of Henle?","o":["15%","25%","35%","45%","85%"],"a":0,"e":"Approximately 15% to 20% of human nephrons are juxtamedullary nephrons with long loops of Henle that descend deep into the renal inner medulla."},
{"id":106,"s":3,"t":"Renal Physiology","q":"Loop diuretics (example, frusemide) inhibit:","o":["Na reabsorption in the collecting duct","carbonic anhydrase in PCT","Na-K-2Cl transport in the thick ascending loop","aquaporins in PCT","Na-K ATPase in PCT"],"a":2,"e":"Loop diuretics such as furosemide block the Na+/K+/2Cl- luminal co-transporter in the thick ascending limb of Henle's loop."},
{"id":107,"s":3,"t":"Renal Physiology","q":"If renal arterial pressure is reduced from 120 mmHg to 90 mmHg:","o":["renal blood flow will be maintained near control values due primarily to efferent arteriolar dilation","renin secretion from the kidney would decrease","the glomerular filtration rate would be maintained near control values","the clearance of PAH would decrease by approximately 30%","None of the above"],"a":2,"e":"Autoregulation (myogenic and tubuloglomerular feedback mechanisms) maintains GFR and RBF virtually constant across arterial pressures between 80 and 180 mmHg."},
{"id":108,"s":3,"t":"Renal Physiology","q":"If the clearance of Substance X is less than the clearance of inulin, it is most likely that Substance X is:","o":["bound to tubular proteins","bound to plasma proteins","secreted","partly reabsorbed","neither secreted nor reabsorbed"],"a":3,"e":"Inulin clearance equals GFR. If Cx < Cinulin, a portion of the filtered load of Substance X must undergo net tubular reabsorption back into the blood."},
{"id":109,"s":3,"t":"Renal Physiology","q":"Water permeability is:","o":["High in the proximal tubule","Low in the descending limb of Henle's loop","High in the ascending limb of Henle's loop","Low in the collecting duct when ADH is present","Decreased in the collecting duct by agents which block the breakdown of cyclic AMP"],"a":0,"e":"The proximal convoluted tubule is constitutively highly permeable to water due to abundant luminal aquaporin-1 channels, resulting in iso-osmotic fluid reabsorption."},
{"id":110,"s":3,"t":"Renal Physiology","q":"The effect of antidiuretic hormone (ADH) on the kidney is to:","o":["increase the permeability of the distal nephron to water","increase the excretion of Na+","increase the excretion of water","increase the diameter of the renal artery","production of acidic urine"],"a":0,"e":"ADH binds to V2 receptors on principal cells in late distal tubules and collecting ducts, inserting aquaporin-2 water channels to increase water permeability."},
{"id":111,"s":3,"t":"Renal Physiology","q":"Urinary volume is increased by all the following except:","o":["diabetes insipidus","diabetes mellitus","increased renal arterial pressure","infusion of mannitol","None of the above"],"a":4,"e":"Diabetes insipidus, diabetes mellitus, elevated renal arterial pressure (pressure diuresis), and mannitol infusion all act as potent physiological triggers that increase urinary volume."},
{"id":112,"s":3,"t":"Renal Physiology","q":"The plasma concentration at which a particular substance begins to appear in the urine is the:","o":["transport maximum (Tm)","fractional excretion","filtered load","renal threshold","tubular transport"],"a":3,"e":"The renal threshold is the plasma concentration at which the filtered load exceeds the tubular transport reabsorptive capacity (Tm), causing the substance to spill into the urine."},
{"id":113,"s":3,"t":"Renal Physiology","q":"Renin is produced and secreted from granules located in the:","o":["mesangial cells","intercalated cells","afferent arteriole","efferent arteriole","juxtaglomerular cells"],"a":4,"e":"Renin is synthesized, stored, and secreted by modified smooth muscle juxtaglomerular (JG) cells in the walls of afferent arterioles."},
{"id":114,"s":3,"t":"Renal Physiology","q":"The normal human glomerular filtration rate (GFR) is approximately (in ml/min):","o":["100","125","200","300","50"],"a":1,"e":"Average normal GFR in a healthy adult male is 125 mL/min (approximately 180 L/day)."},
{"id":115,"s":3,"t":"Renal Physiology","q":"The renal 'countercurrent' mechanism is dependent upon the anatomic relationship between:","o":["the distal tubule and the macula densa","the loop of Henle and the macula densa","the loop of Henle and the vasa recta","the glomerulus and the afferent and efferent arterioles","the glomerulus and the proximal tubule"],"a":2,"e":"The countercurrent multiplier (Loop of Henle) and countercurrent exchanger (vasa recta capillaries) work together in the renal medulla to establish and preserve hypertonicity."},
{"id":116,"s":3,"t":"Renal Physiology","q":"What is the name for the entry point to the kidney for nerves, blood vessels, ureters and lymphatics?","o":["calyx","hilus","pelvis","pyramid","cortex"],"a":1,"e":"The renal hilum (hilus) is the vertical fissure on the medial border of the kidney through which the renal artery, renal vein, lymphatic vessels, nerves, and renal pelvis pass."},
{"id":117,"s":3,"t":"Renal Physiology","q":"Kidneys have a direct effect on which of the following:","o":["Total blood volume","pH","How much water a person excretes","Blood pressure","all of the above"],"a":4,"e":"The kidneys directly regulate ECF/total blood volume, systemic blood pressure, plasma pH, and urinary water excretion."},
{"id":118,"s":3,"t":"Renal Physiology","q":"The 'brush border' is most extensive in cells of the:","o":["Medullary collecting duct","collecting duct","loop of Henle","DCT","PCT"],"a":4,"e":"Proximal Convoluted Tubule (PCT) epithelial cells possess an extensive apical brush border composed of dense microvilli to maximize surface area for reabsorption."},
{"id":119,"s":3,"t":"Renal Physiology","q":"How do the kidneys contribute to the regulation of acid-base balance in the body?","o":["By producing bicarbonate ions","By secreting hydrogen ions","By regulating respiratory rate","By releasing carbon dioxide","By producing glucose"],"a":1,"e":"The kidneys regulate extracellular fluid pH long-term by actively secreting hydrogen ions (H+) into the tubular lumen and reabsorbing or generating bicarbonate ions (HCO3-)."},
{"id":120,"s":3,"t":"Renal Physiology","q":"Which of the following is a function of the kidneys in glucose metabolism?","o":["Gluconeogenesis","Glycogenolysis","Glycogenesis","Glucose oxidation","Lipolysis"],"a":0,"e":"During prolonged fasting or starvation, the renal proximal convoluted tubules synthesize glucose from non-carbohydrate precursors (such as glutamine) through gluconeogenesis."},
{"id":121,"s":3,"t":"Renal Physiology","q":"What is the role of the kidneys in detoxification?","o":["Filtering toxins from the blood","Producing bile","Metabolizing drugs","Synthesizing enzymes","Storing toxins in adipose tissue"],"a":0,"e":"The kidneys clear foreign toxins, metabolic waste products (urea, uric acid, creatinine), and drug metabolites from the plasma via glomerular filtration and tubular secretion."},
{"id":122,"s":3,"t":"Renal Physiology","q":"How do the kidneys contribute to the regulation of blood volume?","o":["By producing erythropoietin","By regulating heart rate","By secreting antidiuretic hormone (ADH)","By activating the renin-angiotensin-aldosterone system","By increasing peripheral resistance"],"a":3,"e":"Reduced renal perfusion or low ECF volume triggers juxtaglomerular cells to release renin, activating the RAAS cascade to promote renal sodium and water retention, thereby increasing blood volume."},
{"id":123,"s":3,"t":"Renal Physiology","q":"Which condition is characterized by the presence of blood in urine?","o":["Glomerulonephritis","Nephrotic syndrome","Renal cell carcinoma","Pyelonephritis","Hematuria"],"a":4,"e":"Hematuria is defined as the abnormal presence of red blood cells or intact blood in the urine."},
{"id":124,"s":3,"t":"Renal Physiology","q":"How do the kidneys respond to low blood pressure?","o":["By increasing aldosterone secretion","By increasing glomerular filtration rate","By decreasing renin secretion","By constricting afferent arterioles","By dilating efferent arterioles"],"a":0,"e":"Low systemic blood pressure stimulates renal renin release, producing Angiotensin II, which directly triggers the adrenal cortex to secrete aldosterone to restore blood pressure and ECF volume."},
{"id":125,"s":3,"t":"Renal Physiology","q":"How does the renin-angiotensin-aldosterone system (RAAS) regulate blood pressure?","o":["By increasing sodium excretion","By dilating arterioles","By increasing atrial natriuretic peptide (ANP) secretion","By promoting vasodilation","By increasing water retention"],"a":4,"e":"Aldosterone acts on principal cells of the late distal tubule and collecting duct to stimulate sodium and secondary osmotic water retention, elevating ECF volume and blood pressure."},
{"id":126,"s":3,"t":"Renal Physiology","q":"Which condition is characterized by the formation of kidney stones?","o":["Glomerulonephritis","Nephrotic syndrome","Renal cell carcinoma","Pyelonephritis","Nephrolithiasis"],"a":4,"e":"Nephrolithiasis is the clinical term for renal calculus formation (kidney stones) in the renal pelvis and urinary tract."},
{"id":127,"s":3,"t":"Renal Physiology","q":"What is the primary cause of glomerulonephritis?","o":["Chronic dehydration","Immune system dysfunction","Excessive protein intake","Exposure to toxic chemicals","Hormonal imbalance"],"a":1,"e":"Glomerulonephritis is primarily an immune-mediated disorder caused by antigen-antibody complex deposition or autoantibody formation targeting the glomerular basement membrane."},
{"id":128,"s":3,"t":"Renal Physiology","q":"What is the primary function of the urinary bladder?","o":["Filtration of blood","Production of urine","Storage of urine","Reabsorption","Secretion"],"a":2,"e":"The urinary bladder acts as a temporary reservoir that stores urine until it is voluntarily or reflexively voided during micturition."},
{"id":129,"s":3,"t":"Renal Physiology","q":"How does tubuloglomerular feedback contribute to renal autoregulation?","o":["By secreting antidiuretic hormone (ADH)","By sensing changes in sodium concentration in the tubule","By promoting sodium reabsorption in the distal convoluted tubule","By enhancing glomerular filtration rate (GFR) during decreased blood pressure","By adjusting the diameter of the efferent arteriole"],"a":1,"e":"Chemoreceptors in the macula densa sense changes in tubular NaCl concentration and send paracrine signals to alter afferent arteriolar diameter, stabilizing GFR and RBF."},
{"id":130,"s":3,"t":"Renal Physiology","q":"How does increased sodium chloride concentration in the tubule affect autoregulation?","o":["It causes vasoconstriction of afferent arterioles","It leads to vasodilation of efferent arterioles","It decreases renin secretion","It promotes sodium reabsorption in the proximal tubule","It inhibits the release of antidiuretic hormone (ADH)"],"a":0,"e":"Elevated NaCl delivery to the macula densa triggers afferent arteriolar vasoconstriction, lowering glomerular hydrostatic pressure and returning GFR back to normal."},
{"id":131,"s":3,"t":"Renal Physiology","q":"What role do nitric oxide and prostaglandins play in renal autoregulation?","o":["They promote vasoconstriction of afferent arterioles","They inhibit renin secretion from the juxtaglomerular cells","They enhance sympathetic nervous system activity","They mediate vasodilation of afferent arterioles","They stimulate sodium reabsorption in the distal convoluted tubule"],"a":3,"e":"Renal prostaglandins (PGE2, PGI2) and nitric oxide act as local autacoids that induce afferent arteriolar vasodilation to prevent excessive reductions in GFR under vasoconstrictor stress."},
{"id":132,"s":3,"t":"Renal Physiology","q":"What is the main determinant of glomerular filtration rate (GFR) according to the Starling forces?","o":["Hydrostatic pressure in the glomerular capillaries","Hydrostatic pressure in Bowman's space","Colloid osmotic pressure in the glomerular capillaries","Colloid osmotic pressure in Bowman's space","Net filtration pressure"],"a":4,"e":"GFR is directly determined by the net filtration pressure (NFP), which represents the algebraic sum of capillary hydrostatic, capsular hydrostatic, and colloid osmotic pressures across the glomerular membrane."},
{"id":133,"s":3,"t":"Renal Physiology","q":"How does constriction of the afferent arteriole affect glomerular filtration rate (GFR)?","o":["Increases GFR","Decreases GFR","No effect on GFR","Depends on other factors","Leads to uremia"],"a":1,"e":"Afferent arteriolar constriction reduces downstream glomerular capillary hydrostatic pressure (P_GC) and renal blood flow, leading to a decrease in GFR."},
{"id":134,"s":3,"t":"Renal Physiology","q":"How do the kidneys respond to respiratory alkalosis?","o":["Increase bicarbonate reabsorption","Decrease bicarbonate reabsorption","Increase hydrogen ion secretion","Decrease hydrogen ion secretion","No response by the kidneys"],"a":1,"e":"In respiratory alkalosis (low PaCO2), the reduced tubular H+ secretion decreases bicarbonate reabsorption, increasing urinary HCO3- excretion to lower plasma pH toward normal."},
{"id":135,"s":3,"t":"Renal Physiology","q":"What is the main function of bicarbonate ions in the body?","o":["Muscle contraction","Nerve impulse transmission","Oxygen transport","Maintenance of acid-base balance","Regulation of blood pressure"],"a":3,"e":"Bicarbonate (HCO3-) serves as the primary extracellular buffer system in the human body, defending plasma pH against acute acid-base disturbances."},
{"id":136,"s":3,"t":"Renal Physiology","q":"Which of the following is the main electrolyte involved in muscle contraction and nerve impulse transmission?","o":["Sodium (Na+)","Potassium (K+)","Calcium (Ca2+)","Chloride (Cl-)","Bicarbonate (HCO3-)"],"a":2,"e":"Calcium ions enter the axon terminal to trigger neurotransmitter exocytosis during nerve impulse transmission and bind to troponin C to initiate skeletal and cardiac muscle contraction."},
{"id":137,"s":3,"t":"Renal Physiology","q":"How does sodium retention contribute to the development of edema?","o":["By increasing capillary permeability","By enhancing lymphatic drainage","By reducing capillary hydrostatic pressure","By increasing plasma oncotic pressure","By causing osmotic imbalance and water retention"],"a":4,"e":"Excess renal sodium retention increases ECF osmolality and water retention, expanding plasma and interstitial volumes, elevating capillary hydrostatic pressure, and promoting edema."},
{"id":138,"s":3,"t":"Renal Physiology","q":"Which body fluid compartment has the highest concentration of proteins?","o":["Intracellular fluid (ICF)","Extracellular fluid (ECF)","Plasma","Interstitial fluid","Transcellular fluid"],"a":0,"e":"Intracellular fluid contains the highest total protein concentration in the body (~3 times that of plasma) to maintain cellular structure, enzyme pathways, and oncotic equilibrium."},
{"id":139,"s":2,"t":"Cardiovascular Physiology","q":"The following exhibit the tendency and ability for self-excitation or automaticity EXCEPT:","o":["SA Nodal cells","AV Nodal cells","Interventricular septum","Purkinje fibres","Bundle of His"],"a":2,"e":"Autorhythmic conducting cells (SA node, AV node, Bundle of His, Purkinje fibers) possess pacemaker prepotentials and automaticity, whereas working ventricular myocytes in the septum possess stable resting potentials (-90 mV)."},
{"id":140,"s":2,"t":"Cardiovascular Physiology","q":"Concerning the isovolumetric relaxation phase of the cardiac cycle the following is INCORRECT:","o":["The semilunar valves are closed and the AV valves are also closed","The snapping of the Semilunar valves occurs in this phase","The ventricles are just beginning to relax","The pressure in the ventricles is less than the pressure in the atria","The pressure in the arterial system is greater than that in the ventricles"],"a":3,"e":"During isovolumetric relaxation, ventricular pressure remains higher than atrial pressure (keeping the AV valves closed). Only when ventricular pressure drops below atrial pressure do the AV valves open."},
{"id":141,"s":2,"t":"Cardiovascular Physiology","q":"About the force of contraction:","o":["The end systolic volume represents the preload","The end diastolic volume represents the afterload","The higher the preload, the higher the stroke volume","The higher the preload, the lower the stroke volume","The higher the afterload, the higher the stroke volume"],"a":2,"e":"According to the Frank-Starling law of the heart, increasing end-diastolic volume (preload) increases myocardial muscle fiber stretch, boosting the force of contraction and stroke volume."},
{"id":142,"s":2,"t":"Cardiovascular Physiology","q":"Which of the following combinations will maximally increase the heart rate?","o":["Sympathetic stimulation + Parasympathetic stimulation","Parasympathetic stimulation + Infusion of calcium ions","Thyroid hormones + Parasympathetic stimulation","Infusion of calcium ions + Sympathetic stimulation","None of the above"],"a":3,"e":"Sympathetic stimulation (via beta-1 receptors) and elevated ECF calcium ions increase inward Ca2+ current during phase 0/4 depolarization, accelerating SA nodal discharge and heart rate."},
{"id":143,"s":2,"t":"Cardiovascular Physiology","q":"Baroreceptor mechanisms are classified under which of the following?","o":["Short term nervous regulation","Medium term nervous regulation","Indirect long term regulation","Short term hormonal regulation","Direct long term regulation"],"a":0,"e":"Arterial baroreceptor reflexes respond within seconds to acute fluctuations in blood pressure, providing rapid, short-term neural hemodynamic control."},
{"id":144,"s":2,"t":"Cardiovascular Physiology","q":"The following are directly involved in the regulation of blood pressure except?","o":["Cortisol","Aldosterone","ADH","Angiotensin II","Renin"],"a":0,"e":"While RAAS components (Angiotensin II, Aldosterone) and ADH directly control vascular tone and renal fluid balance, cortisol is a glucocorticoid primarily regulating carbohydrate metabolism and stress responses."},
{"id":145,"s":2,"t":"Cardiovascular Physiology","q":"The functions of Angiotensin II include the following:","o":["Vasoconstriction","Stimulates release of Aldosterone","Causes the release of anti-diuretic hormone","Triggers the thirst sensations","All the above"],"a":4,"e":"Angiotensin II causes potent arteriolar vasoconstriction, stimulates adrenal aldosterone release, triggers posterior pituitary ADH secretion, and acts on the hypothalamus to stimulate thirst."},
{"id":146,"s":2,"t":"Cardiovascular Physiology","q":"The following are manifestations of hypovolemic shock except:","o":["Decreased cardiac output","Low blood pressure","Thin thready pulse","Restlessness and lethargy","Decreased respiratory rate"],"a":4,"e":"Hypovolemic shock leads to hypotension, tachycardia, oliguria, pale cold skin, and compensatory hyperventilation (increased respiratory rate) driven by lactic acidosis."},
{"id":147,"s":2,"t":"Cardiovascular Physiology","q":"About the action potential in nodal cells:","o":["RMP is about -60mV","Funny sodium channels play an important role","At threshold potential, L type calcium channels open","When the cells are depolarised calcium influx stops and potassium efflux starts","All of the above"],"a":4,"e":"SA/AV nodal pacemaker cells have an unstable RMP (~-60 mV), rely on funny Na+ channels (If) for prepotentials, depolarize via L-type Ca2+ channels at threshold, and repolarize via K+ efflux."},
{"id":148,"s":2,"t":"Cardiovascular Physiology","q":"Protein kinase A acts directly on which of the following?","o":["L-type calcium channels","T-type calcium channels","Funny sodium channels","Potassium channels","None of the above"],"a":0,"e":"Sympathetic stimulation elevates cAMP, activating Protein Kinase A (PKA) to phosphorylate L-type Ca2+ channels and phospholamban, increasing calcium influx and contractility."},
{"id":149,"s":2,"t":"Cardiovascular Physiology","q":"Measurement of cerebral and coronary blood flow can be carried out by which of the following methods?","o":["Kety method","Dye-dilution method","Kalahari method","Electromagnetic flowmeter","Doppler method"],"a":0,"e":"The Kety nitrous oxide clearance method based on the Fick principle is a classic technique used to measure cerebral and tissue blood flow."},
{"id":150,"s":2,"t":"Cardiovascular Physiology","q":"The oxygen saturation during fetal life is approximately:","o":["20%","25%","99%","70%","50%"],"a":3,"e":"Oxygenated blood coming from the placenta via the umbilical vein has a maximal fetal oxygen saturation of approximately 70% to 80%."},
{"id":151,"s":2,"t":"Cardiovascular Physiology","q":"Atrial repolarization is represented by which of the following on an ECG tracing?","o":["U wave","QRS complex","P wave","ST segment","None of the above"],"a":4,"e":"Atrial repolarization (atrial T wave) occurs during ventricular depolarization and is masked/buried inside the QRS complex."},
{"id":152,"s":2,"t":"Cardiovascular Physiology","q":"One small and large box on an ECG tracing represents which of the following respectively?","o":["0.02sec and 0.4sec","0.4sec and 0.02sec","0.04sec and 0.2sec","0.2sec and 0.04sec","0.08sec and 0.40sec"],"a":2,"e":"Standard ECG paper running at 25 mm/s is calibrated such that 1 small box (1 mm) = 0.04 seconds and 1 large box (5 mm) = 0.20 seconds."},
{"id":153,"s":2,"t":"Cardiovascular Physiology","q":"Tall peaked T waves are usually ECG manifestations of early?","o":["Hypokalemia","Hyperkalemia","Hypocalcemia","Hypercalcemia","Hypernatremia"],"a":1,"e":"Elevated plasma potassium (hyperkalemia) accelerates repolarization, producing characteristically tall, narrow, and peaked T waves on the ECG."},
{"id":154,"s":2,"t":"Cardiovascular Physiology","q":"Which of the following blood vessel layers is present in a capillary?","o":["Tunica externa","Tunica adventitia","Tunica intima","Tunica media","Tunica albuginea"],"a":2,"e":"True capillaries consist solely of a single endothelial cell layer (tunica intima) resting on a basal lamina, lacking tunica media or externa."},
{"id":155,"s":2,"t":"Cardiovascular Physiology","q":"The relationship between the flow of fluid in a narrow tube, the viscosity of the fluid and radius of the tube can be expressed by:","o":["Frank-Starling law","Laplace law","Poiseuille-Hagen formula","All of the above","None of the above"],"a":2,"e":"Poiseuille's Law states that blood flow is directly proportional to pressure difference and the fourth power of vessel radius (r^4), and inversely proportional to fluid viscosity and vessel length."},
{"id":156,"s":2,"t":"Cardiovascular Physiology","q":"The blood flow in blood vessels can be measured directly by:","o":["Electromagnetic flowmeter","Dye-dilution method","Fick's principle","Echocardiography","Plethysmography"],"a":0,"e":"Electromagnetic and ultrasonic Doppler flowmeters allow direct, instantaneous recording of blood flow in intact blood vessels."},
{"id":157,"s":1,"t":"Gastrointestinal Physiology","q":"From outer to inner layer, which is the correct order of the GIT wall?","o":["Serosa -> circular smooth muscle -> longitudinal smooth muscle","Serosa -> longitudinal smooth muscle -> circular smooth muscle -> submucosa -> mucosa","Mucosa -> submucosa -> circular smooth muscle -> longitudinal smooth muscle","Longitudinal smooth muscle -> serosa -> circular smooth muscle -> submucosa -> mucosa","None of the above"],"a":1,"e":"From the outer peritoneal surface inward, the gut wall layers are: Serosa, Longitudinal muscle, Myenteric plexus, Circular muscle, Submucosa (Meissner's plexus), Muscularis mucosae, and Mucosa."},
{"id":158,"s":1,"t":"Gastrointestinal Physiology","q":"Which of the following is NOT correct?","o":["The GIT has its own nervous system","Another name for myenteric plexus is Meissner's plexus","The myenteric plexus controls GI motility","The submucosal plexus controls GI secretion","Contraction of muscularis mucosa aids absorption"],"a":1,"e":"The myenteric plexus is Auerbach's plexus (controls motility), whereas Meissner's plexus is the submucosal plexus (controls secretions)."},
{"id":159,"s":1,"t":"Gastrointestinal Physiology","q":"Stimulation of GI movements occurs by the following EXCEPT:","o":["Gut wall distension","Chemical irritation","Physical exercise","Smell of food","Sight of food"],"a":2,"e":"Heavy physical exercise triggers intense sympathetic stimulation and splanchnic vasoconstriction, which inhibits gastrointestinal motility and secretions."},
{"id":160,"s":1,"t":"Gastrointestinal Physiology","q":"Composition of pancreatic juice includes the following EXCEPT:","o":["Proteolytic enzymes","Lipolytic enzymes","Amylolytic enzymes","Anxiolytic enzymes","Bicarbonate"],"a":3,"e":"Pancreatic juice contains digestive enzymes for proteins (trypsin, chymotrypsin), lipids (lipase, phospholipase), and carbohydrates (amylase), but no 'anxiolytic' enzymes."},
{"id":161,"s":1,"t":"Gastrointestinal Physiology","q":"The GIT is divided into compartments by:","o":["Varying thickness of gut wall","Types of epithelium","Shape of lumen","Size of lumen","GI sphincters"],"a":4,"e":"Specialized gastrointestinal sphincters (LES, pyloric, ileocecal, internal/external anal sphincters) separate functional regions of the digestive tract and regulate movement."},
{"id":162,"s":1,"t":"Gastrointestinal Physiology","q":"What is the primary site for nutrient absorption in the GIT?","o":["Stomach","Duodenum","Jejunum","Ileum","Caecum"],"a":2,"e":"The jejunum contains extensive mucosal plicae circulares and villi, making it the primary site for the absorption of carbohydrates, proteins, and water-soluble vitamins."},
{"id":163,"s":1,"t":"Gastrointestinal Physiology","q":"Concerning mastication, one is INCORRECT:","o":["Aids swallowing","Helps digestion of carbohydrates","It is mainly voluntary","Achieves appreciation of taste of food","Aids lubrication of dry foods"],"a":2,"e":"While chewing can be initiated voluntarily, it is predominantly an involuntary reflex act coordinated by the brainstem trigeminal motor nucleus."},
{"id":164,"s":1,"t":"Gastrointestinal Physiology","q":"Concerning swallowing, identify the FALSE statement:","o":["Also known as deglutition","Elevation of soft palate closes the nasopharynx","Backward movement of epiglottis closes the larynx","Pharyngeal stage is both voluntary and involuntary","The vagus nerve is involved in esophageal stage"],"a":3,"e":"The pharyngeal stage of deglutition is completely involuntary (reflexive); only the initial oral stage is voluntary."},
{"id":165,"s":1,"t":"Gastrointestinal Physiology","q":"Components of gastric juice does NOT include one of the following:","o":["Hydrochloric acid","Pepsinogen","Mucus","Extrinsic factor","Intrinsic factor"],"a":3,"e":"Extrinsic factor is dietary Vitamin B12, whereas Intrinsic Factor is the glycoprotein secreted by gastric parietal cells required for B12 absorption."},
{"id":166,"s":1,"t":"Gastrointestinal Physiology","q":"Which cells in the stomach produce HCL?","o":["Parietal cells","Chief cells","Oxyntic cells","Pyloric cells","Goblet cells"],"a":0,"e":"Parietal (oxyntic) cells in the gastric oxyntic glands secrete hydrochloric acid (HCl) via H+/K+-ATPase proton pumps."},
{"id":167,"s":1,"t":"Gastrointestinal Physiology","q":"What is the function of the ileocaecal valve?","o":["To prevent backflow of faecal matter into the small intestines","To control the release of pancreatic enzymes into the small intestines","To regulate the release of bile from the gallbladder","To control the passage of chyme from the small intestine into the large intestines","To aid enterohepatic circulation"],"a":0,"e":"The ileocecal valve and sphincter prevent reflux of cecal/fecal contents and bacteria back into the ileum."},
{"id":168,"s":1,"t":"Gastrointestinal Physiology","q":"Concerning gastric emptying:","o":["Acidic foods empty faster than alkaline foods","Proteins empty faster than carbohydrates","Takes about 2-3 hours","The more the food, the faster the emptying","None of the above"],"a":3,"e":"Increased gastric food volume stretches the stomach wall, eliciting local myenteric reflexes and gastrin release that enhance pyloric pump contractions to accelerate emptying."},
{"id":169,"s":1,"t":"Gastrointestinal Physiology","q":"Identify the ODD one out:","o":["Parotid gland","Submucosal gland","Submaxillary gland","Submandibular gland","Sublingual gland"],"a":1,"e":"Parotid, submandibular (submaxillary), and sublingual glands are the three pairs of major salivary glands."},
{"id":170,"s":1,"t":"Gastrointestinal Physiology","q":"Which of these is NOT correctly matched?","o":["Migrating myoelectric complexes / motilin","Slow waves / basic electrical rhythm","Rectosphincteric reflex / external anal sphincter","Receptive relaxation / vagovagal reflex","Parotid gland / Stensen duct"],"a":2,"e":"The rectosphincteric (defecation) reflex causes involuntary relaxation of the internal anal sphincter; the external anal sphincter is under voluntary somatic (pudendal nerve) control."},
{"id":171,"s":1,"t":"Gastrointestinal Physiology","q":"Which of the following is the main site of bile acid reabsorption in the small intestine?","o":["Duodenum","Jejunum","Ileum","Caecum","Peyer's patches"],"a":2,"e":"More than 95% of bile salts are reabsorbed in the terminal ileum via secondary active Na+-bile acid cotransporters into the enterohepatic circulation."},
{"id":172,"s":1,"t":"Gastrointestinal Physiology","q":"Which of the following sphincters regulates the release of bile into the duodenum?","o":["Pyloric sphincter","Sphincter of Oddi","Sphincter of Vater","Ileocaecal sphincter","Anal sphincter"],"a":1,"e":"The Sphincter of Oddi guards the choledochoduodenal junction at the ampulla of Vater, relaxing under the influence of CCK to release bile and pancreatic juice."},
{"id":173,"s":1,"t":"Gastrointestinal Physiology","q":"What are chylomicrons?","o":["Another name for triglycerides","Simplest form of chyme","Lipid-carrying particles","Newly absorbed monosaccharides","Newly absorbed bile salts"],"a":2,"e":"Chylomicrons are large lipoprotein droplets synthesized by enterocytes containing re-esterified triglycerides, cholesterol, and apolipoprotein B-48 that enter the intestinal lacteals."},
{"id":174,"s":1,"t":"Gastrointestinal Physiology","q":"Which of the following hormones stimulates the gallbladder to contract?","o":["Secretin","Gastrin","Somatostatin","Cholecystokinin","Motilin"],"a":3,"e":"Cholecystokinin (CCK), released from duodenal I cells in response to fatty acids and peptides, causes gallbladder smooth muscle contraction and Sphincter of Oddi relaxation."},
{"id":175,"s":1,"t":"Gastrointestinal Physiology","q":"Concerning absorption of monosaccharides:","o":["Glucose constitutes 20% of absorbed monosaccharides","Galactose and fructose constitute 80% of absorbed monosaccharides","Fructose is transported into the enterocyte by GLUT-2","Glucose and galactose are transported into the enterocyte by SGLT-1","Glucose and galactose are transported across the basolateral membrane by GLUT-5"],"a":3,"e":"Glucose and galactose enter luminal enterocyte membranes via Sodium-Glucose Cotransporter 1 (SGLT-1), whereas fructose enters via GLUT-5, and all three exit basolaterally via GLUT-2."},
{"id":176,"s":1,"t":"Gastrointestinal Physiology","q":"Identify the ODD one out:","o":["Antacids","H2-receptor blockers","Muscarinic blockers","Prostaglandins","H-K ATPase inhibitors"],"a":3,"e":"Prostaglandins (PGE2) are cytoprotective mucosal defense agents, whereas Antacids, H2-blockers, Muscarinic blockers, and H+/K+-ATPase inhibitors are gastric acid suppressing/neutralizing pharmacotherapies."},
{"id":177,"s":2,"t":"Cardiovascular Physiology","q":"Blood pressure is defined as:","o":["The force exerted by blood on the heart","The velocity of blood flow through the arteries","The resistance of blood flow in the veins","The force exerted by blood against vessel walls","The volume of blood pumped by the heart per minute"],"a":3,"e":"Arterial blood pressure is defined as the lateral force or pressure exerted by the moving column of blood against the vessel walls."},
{"id":178,"s":2,"t":"Cardiovascular Physiology","q":"The term 'systolic blood pressure' refers to:","o":["The pressure in the arteries during ventricular contraction","The pressure in the arteries during ventricular relaxation","The pressure in the veins during ventricular contraction","The pressure in the veins during ventricular relaxation","The pressure in the capillaries during blood clotting"],"a":0,"e":"Systolic blood pressure represents the peak pressure in the systemic arteries during ventricular contraction (systole)."},
{"id":179,"s":2,"t":"Cardiovascular Physiology","q":"Which of the following is NOT a factor influencing peripheral resistance?","o":["Blood viscosity","Vessel length","Vessel elasticity","Vessel diameter","Heart rate"],"a":4,"e":"Vascular resistance depends on blood viscosity, vessel length, vessel elasticity, and vessel lumen diameter/radius; heart rate influences cardiac output rather than peripheral resistance."},
{"id":180,"s":2,"t":"Cardiovascular Physiology","q":"What effect does increased hematocrit (percentage of red blood cells in blood) have on blood pressure?","o":["Increases blood pressure","Decreases blood pressure","No effect on blood pressure","Increases heart rate","Decreases stroke volume"],"a":0,"e":"An elevated hematocrit raises blood viscosity, which increases peripheral vascular resistance and elevates arterial blood pressure."},
{"id":181,"s":2,"t":"Cardiovascular Physiology","q":"Which of the following factors contributes to the maintenance of blood pressure during prolonged standing?","o":["Increased skeletal muscle pump activity","Decreased venous pressure","Increased baroreceptor sensitivity","Decreased capillary hydrostatic pressure","Reduced sympathetic nervous system activity"],"a":2,"e":"Gravitational pooling of blood upon standing reduces venous return; the reflex activation of arterial baroreceptors triggers compensatory sympathetic vasoconstriction and heart rate elevation to maintain blood pressure."},
{"id":182,"s":2,"t":"Cardiovascular Physiology","q":"The following occur during atrial systole except.","o":["70-80% ventricular filling","Atria contract","20-30% ventricular filling","Sudden rise in atrial pressure","Ventricles attain End Diastolic Volume (EDV)"],"a":0,"e":"Passive ventricular filling during early-to-mid diastole accounts for 70–80% of filling; active atrial contraction (atrial systole) provides only the final 20–30% of ventricular volume."},
{"id":183,"s":2,"t":"Cardiovascular Physiology","q":"Concerning ventricular systole the following is/are correct:","o":["Aortic and pulmonary valves close when ventricular pressure exceeds pressure in aorta and pulmonary artery.","The ventricles are closed chambers during isovolumetric contraction.","End systolic volume (ESV) is about 90mls.","Ejection fraction is stroke volume (SV) divided by end diastolic volume (EDV) expressed as a percentage","B and D are correct."],"a":4,"e":"During isovolumetric contraction, all heart valves are closed, making the ventricles closed chambers. Ejection fraction is calculated as Stroke Volume divided by End Diastolic Volume expressed as a percentage (EF = (SV/EDV) x 100%)."},
{"id":184,"s":2,"t":"Cardiovascular Physiology","q":"ECG depicts the depolarization and repolarization processes during the cardiac cycle. In the ECG of a normal healthy individual one of the following is not represented:","o":["Depolarization of the atria","Depolarization of the ventricles","Repolarization of the atria","Repolarization of the ventricles","Depolarization of both the atria and the ventricles"],"a":2,"e":"Atrial repolarization occurs simultaneously with ventricular depolarization and is obscured/buried by the much larger QRS complex."},
{"id":185,"s":2,"t":"Cardiovascular Physiology","q":"The normal duration of QRS complex is:","o":["0.04 seconds","0.08 seconds","0.16 seconds","0.12 seconds","0.20 seconds"],"a":1,"e":"The normal duration of the QRS complex is less than 0.10 seconds (typically 0.06 to 0.10 seconds)."},
{"id":186,"s":2,"t":"Cardiovascular Physiology","q":"The serous pericardium has the following features except","o":["Has two layers.","Anchors it to surrounding structures.","Serous fluid in it helps the heart function without friction.","Its visceral layer is also called the epicardium.","Excess fluid in it can cause a cardiac tamponade."],"a":1,"e":"Anchoring the heart to surrounding structures (sternum and diaphragm) is a function of the outer fibrous pericardium, whereas the serous pericardium consists of parietal and visceral (epicardium) layers enclosing serous fluid."},
{"id":187,"s":2,"t":"Cardiovascular Physiology","q":"In the heart","o":["All valves are one-way valves.","The mitral valve has three cusps.","Inter atrial and inter ventricular septa are muscular.","Walls of right and left ventricles are equal in thickness.","A and C are correct."],"a":0,"e":"Heart valves open and close passively based on pressure gradients to maintain unidirectional (one-way) blood flow."},
{"id":188,"s":2,"t":"Cardiovascular Physiology","q":"The autorhythmic cells of the cardiac conducting system","o":["Are non-contractile cells.","Have Resting membrane potential (RMP) of about 60mV.","Have an unstable RMP.","Can generate an action potential spontaneously.","All the above are correct."],"a":4,"e":"Autorhythmic cells are non-contractile, have an unstable resting potential starting around -60 mV, and spontaneously generate action potentials."},
{"id":189,"s":2,"t":"Cardiovascular Physiology","q":"The following are true concerning conduction of impulse through the heart except:","o":["Conduction is fastest through the Purkinje fibers.","AV nodal delay is lengthened by sympathetic stimulation.","Intercalated discs and gap junctions facilitate rapid conduction.","Conduction is slowest at SA and AV nodes.","AV nodal delay helps ensure atria empty into ventricles before ventricles contract."],"a":1,"e":"Sympathetic stimulation increases conduction velocity and shortens AV nodal delay; parasympathetic (vagal) stimulation is what lengthens the delay."},
{"id":190,"s":2,"t":"Cardiovascular Physiology","q":"The sudden and simultaneous closure of the semilunar valves is the major cause of:","o":["1st heart sound","3rd heart sound","5th heart sound","2nd heart sound","4th heart sound"],"a":3,"e":"The 2nd heart sound (S2) is caused by the sudden closure of the semilunar (aortic and pulmonary) valves at the beginning of diastole."},
{"id":191,"s":2,"t":"Cardiovascular Physiology","q":"Identify the incorrect statement:","o":["3rd heart sound is associated with rapid ventricular filling","3rd heart sound normally requires a stethoscope to detect them","Synchronous closure of AV valves set up the vibrations in the chordate tendineae","Alteration in the heart sounds indicates cardiac diseases involving valves of the heart","Opening of the valves is usually silent but may be associated with sounds in pathological diseases of the valves"],"a":1,"e":"The 3rd heart sound is a low-frequency vibration caused by rapid ventricular filling that is normally inaudible with a standard stethoscope and requires phonocardiography or specialized recording."},
{"id":192,"s":2,"t":"Cardiovascular Physiology","q":"Continuous murmur occurs in which of the following conditions?","o":["Incompetence of semilunar valves","Stenosis of AV valves","Patent ductus arteriosus","Coarctation of aorta","Septal Defect"],"a":2,"e":"Patent ductus arteriosus (PDA) creates continuous flow from the high-pressure aorta to the lower-pressure pulmonary artery, producing a continuous machinery-like murmur."},
{"id":193,"s":3,"t":"Renal Physiology","q":"Which of the following describes total body water in a healthy adult male?","o":["30%","40%","60%","70%","90%"],"a":2,"e":"Total body water constitutes approximately 60% of total body weight in a healthy adult male."},
{"id":194,"s":3,"t":"Renal Physiology","q":"Osmolarity of a solution refers to:","o":["The amount of water in the body","The number of solute particles per liter of solvent","The number of solvent particles per liter of solution","The total weight of body fluids","None of the above"],"a":4,"e":"Osmolarity is defined as the number of solute particles (osmoles) per liter of solution (Option B incorrectly states per liter of solvent)."},
{"id":195,"s":3,"t":"Renal Physiology","q":"Which of the following is a main function of the kidneys?","o":["Protein synthesis","Blood filtration","Hormone production","Detoxification","Erythropoiesis"],"a":1,"e":"The primary renal process initiating urine formation is the ultrafiltration of blood plasma across glomerular capillaries."},
{"id":196,"s":3,"t":"Renal Physiology","q":"Which fluid compartment holds the most body water?","o":["Plasma","Interstitial fluid","Intracellular fluid","Extracellular fluid","Lymph"],"a":2,"e":"Intracellular fluid (ICF) holds approximately two-thirds (~28 L) of total body water (~42 L)."},
{"id":197,"s":3,"t":"Renal Physiology","q":"The functional unit of the kidney is known as the:","o":["Nephron","Glomerulus","Renal capsule","Loop of Henle","Ureter"],"a":0,"e":"The nephron is the structural and functional unit of the kidney responsible for urine production."},
{"id":198,"s":3,"t":"Renal Physiology","q":"Which of the following is NOT part of the nephron?","o":["Proximal convoluted tubule","Glomerulus","Collecting duct","Distal convoluted tubule","Hilum"],"a":4,"e":"The hilum is an anatomical tissue fissure on the medial concave border of the kidney, not a nephron structure."},
{"id":199,"s":3,"t":"Renal Physiology","q":"How many nephrons are present in each kidney?","o":["500,000","1 million","2 million","1.5 million","3 million"],"a":1,"e":"Each kidney contains approximately 1 to 1.3 million nephrons."},
{"id":200,"s":3,"t":"Renal Physiology","q":"Which part of the nephron is responsible for blood filtration?","o":["Proximal tubule","Loop of Henle","Collecting duct","Glomerulus","Distal tubule"],"a":3,"e":"Ultrafiltration of blood plasma occurs across the glomerular capillary wall into Bowman's space."},
{"id":201,"s":3,"t":"Renal Physiology","q":"Juxtamedullary nephrons differ from cortical nephrons in that they:","o":["Have longer loops of Henle","Are located entirely in the renal cortex","Play no role in urine concentration","Lack afferent arterioles","Are more numerous"],"a":0,"e":"Juxtamedullary nephrons have long loops of Henle extending deep into the inner renal medulla."},
{"id":202,"s":3,"t":"Renal Physiology","q":"The clearance of which substance is used to estimate glomerular filtration rate (GFR)?","o":["Glucose","Inulin","Sodium","Potassium","Urea"],"a":1,"e":"Inulin is freely filtered and neither reabsorbed nor secreted, making its clearance the standard measure for GFR."},
{"id":203,"s":3,"t":"Renal Physiology","q":"Renal plasma flow (RPF) is primarily measured using which substance?","o":["PAH","Inulin","Creatinine","Glucose","Sodium"],"a":0,"e":"Para-aminohippuric acid (PAH) clearance measures effective renal plasma flow because it is filtered and almost completely secreted by renal tubules."},
{"id":204,"s":3,"t":"Renal Physiology","q":"Which of the following is true regarding renal blood flow?","o":["It constitutes about 5% of the total cardiac output","It constitutes about 25% of the total cardiac output","It is not autoregulated","It is reduced by sympathetic stimulation","It increases during hemorrhage"],"a":1,"e":"The kidneys receive approximately 20–25% (~1.25 L/min) of the total cardiac output at rest."},
{"id":205,"s":3,"t":"Renal Physiology","q":"Which vessel is the first to receive blood as it enters the kidney?","o":["Renal artery","Afferent arteriole","Glomerular capillaries","Efferent arteriole","Renal vein"],"a":0,"e":"Blood enters the kidney via the main renal artery before dividing into interlobar, arcuate, and interlobular arteries."},
{"id":206,"s":3,"t":"Renal Physiology","q":"Which part of the nephron has the highest filtration pressure?","o":["Proximal tubule","Loop of Henle","Distal tubule","Glomerulus","Collecting duct"],"a":3,"e":"Glomerular capillaries maintain high hydrostatic pressure (~60 mmHg) to drive plasma ultrafiltration."},
{"id":207,"s":3,"t":"Renal Physiology","q":"Glomerular filtration rate (GFR) is primarily determined by which of the following factors?","o":["Blood pressure","Plasma osmolarity","Filtration fraction","Renal plasma flow","All of the above"],"a":4,"e":"GFR depends on net filtration pressure (hydrostatic/oncotic pressures), filtration coefficient (Kf), and renal plasma flow."},
{"id":208,"s":3,"t":"Renal Physiology","q":"Which of the following pressures opposes glomerular filtration?","o":["Hydrostatic pressure in Bowman's space","Glomerular capillary hydrostatic pressure","Colloid osmotic pressure in Bowman's space","Glomerular filtration pressure","Renal plasma flow"],"a":0,"e":"Bowman's space hydrostatic pressure (PB) and glomerular capillary colloid osmotic pressure (πc) both oppose filtration."},
{"id":209,"s":3,"t":"Renal Physiology","q":"What percentage of plasma entering the glomerulus is typically filtered?","o":["5%","10%","20%","40%","60%"],"a":2,"e":"The normal filtration fraction (GFR / RPF) is approximately 20% (0.20)."},
{"id":210,"s":3,"t":"Renal Physiology","q":"Which of the following is the best marker for measuring GFR?","o":["Creatinine","Inulin","Urea","Glucose","Sodium"],"a":1,"e":"Inulin clearance remains the gold standard exogenous reference marker for GFR measurement."},
{"id":211,"s":3,"t":"Renal Physiology","q":"Which factor would decrease the GFR?","o":["Dilation of the afferent arteriole","Constriction of the efferent arteriole","Increased protein concentration in plasma","Increased blood flow","Decreased Bowman's space hydrostatic pressure"],"a":2,"e":"Elevated plasma protein concentration increases glomerular capillary colloid osmotic pressure, opposing net filtration and decreasing GFR."},
{"id":212,"s":3,"t":"Renal Physiology","q":"Where is most of the sodium reabsorbed in the nephron?","o":["Proximal tubule","Distal tubule","Loop of Henle","Collecting duct","Glomerulus"],"a":0,"e":"Approximately 65% of filtered sodium and water is reabsorbed in the proximal convoluted tubule."},
{"id":213,"s":1,"t":"Gastrointestinal Physiology","q":"Leptin resistance is:","o":["Deficiency of leptin caused by a mutation of leptin gene","Lack of leptin release from adipose tissues","High concentrations of leptin without reduction in energy intake","Low concentrations of leptin with increased energy intake","High concentrations of ghrelin without reduction in energy intake"],"a":2,"e":"Leptin resistance is characterized by elevated circulating leptin levels failing to induce satiety or reduce food intake."},
{"id":214,"s":1,"t":"Gastrointestinal Physiology","q":"Damage in the neural network of the myenteric plexus in the Lower two thirds of the esophagus leads to:","o":["Achalasia","Peptic ulcer","Gastritis","Achlorhydria","Pancreatitis"],"a":0,"e":"Loss of myenteric plexus inhibitory neurons in the lower esophagus causes failure of lower esophageal sphincter (LES) relaxation and esophageal aperistalsis (Achalasia)."},
{"id":215,"s":1,"t":"Gastrointestinal Physiology","q":"Which of the following is a hunger-stimulating compound produced in the brain?","o":["Ghrelin","NPY","POMC","CART","PYY"],"a":1,"e":"Neuropeptide Y (NPY) and AgRP are central orexigenic (hunger-stimulating) peptides produced in the arcuate nucleus of the hypothalamus."},
{"id":216,"s":1,"t":"Gastrointestinal Physiology","q":"Which one of the following is not a complication of GERD?","o":["Erosive esophagitis","Barrett's Esophagus","Iron deficiency anemia","Esophageal stricture","Conn's disease"],"a":4,"e":"Conn's disease (primary aldosteronism) is an adrenal cortex disorder, whereas esophagitis, Barrett's esophagus, strictures, and anemia are GERD complications."},
{"id":217,"s":1,"t":"Gastrointestinal Physiology","q":"Incomplete LES relaxation, increase in LES tone, esophageal a peristalsis is definition of:","o":["Plummer Vinson syndrome","Infectious esophagitis","Achalasia","Pancreatitis","Chorea"],"a":2,"e":"Achalasia is defined by incomplete LES relaxation during swallowing, elevated resting LES tone, and esophageal aperistalsis."},
{"id":218,"s":1,"t":"Gastrointestinal Physiology","q":"All of the following are causes of acute peptic ulcer except:","o":["Severe burns","Helicobacter pylori infection","Prolonged excess acid secretion","Major trauma","Zollinger-Ellison syndrome"],"a":1,"e":"H. pylori causes chronic peptic ulcer disease, whereas severe burns (Curling's ulcer) and major trauma cause acute stress ulcers."},
{"id":219,"s":1,"t":"Gastrointestinal Physiology","q":"Which of the following is the commonest causes of duodenal peptic ulcer?","o":["Duodeno-gastric reflux","H pylori infection","Acute pancreatitis","NSAIDS","All of the above"],"a":1,"e":"Chronic infection with Helicobacter pylori is responsible for over 85% of duodenal ulcers."},
{"id":220,"s":1,"t":"Gastrointestinal Physiology","q":"Which of the following neurons mentioned promotes the increased drive to consume food:","o":["Activated AgRP","Activated POMC","Activated CGRP","Activated PIKC","Activated PPRP"],"a":0,"e":"Agouti-related peptide (AgRP) neurons in the hypothalamus promote hyperphagia and increase the drive to eat."},
{"id":221,"s":1,"t":"Gastrointestinal Physiology","q":"Which organ secretes trypsinogen?","o":["Stomach","Liver","Small intestine","Pancreas","Gallbladder"],"a":3,"e":"Pancreatic acinar cells synthesize and secrete inactive trypsinogen into pancreatic juice."},
{"id":222,"s":1,"t":"Gastrointestinal Physiology","q":"Which enzyme activates trypsinogen to trypsin in the small intestine?","o":["Pepsin","Chymotrypsin","Enterokinase","Amylase","Sur"],"a":2,"e":"Enterokinase (enteropeptidase) on the duodenal mucosal brush border activates trypsinogen into active trypsin."},
{"id":223,"s":1,"t":"Gastrointestinal Physiology","q":"Which cells in the stomach secrete hydrochloric acid to activate pepsinogen?","o":["Chief cells","Parietal cells","Goblet cells","Pancreatic cells","Entericytes"],"a":1,"e":"Parietal (oxyntic) cells in gastric glands secrete hydrochloric acid (HCl)."},
{"id":224,"s":1,"t":"Gastrointestinal Physiology","q":"What is the role of pancreatic amylase in carbohydrate digestion?","o":["To convert maltose to glucose","To convert starch into maltose","To break down sucrose into glucose and fructose","To emulsify fats","To absorb glucose from the intestine"],"a":1,"e":"Pancreatic alpha-amylase hydrolyzes complex starches into maltose and short glucose polymers in the small intestine."},
{"id":225,"s":1,"t":"Gastrointestinal Physiology","q":"Identify the incorrect statement:","o":["CCK acts via the receptor CCK-A","CCK causes emptying of the gall bladder","CCK stimulates appetite","Secretin may contract the pyloric sphincter","VIP potentiates the action of Ach on salivary glands"],"a":2,"e":"Cholecystokinin (CCK) acts as a satiety hormone that suppresses appetite and reduces meal size."},
{"id":226,"s":1,"t":"Gastrointestinal Physiology","q":"The GI hormone which acts on the cells of pancreatic ductule via cyclic AMP is:","o":["Motilin","Vasoactive Intestinal Polypeptide","Secretin","GIP","Cholecystokinin"],"a":2,"e":"Secretin binds to ductal epithelial cell receptors, elevating cAMP to stimulate bicarbonate secretion."},
{"id":227,"s":1,"t":"Gastrointestinal Physiology","q":"Which of the following inhibits gastric secretion?","o":["Gastric Inhibitory polypeptide","Secretin","Cholecystokinin","Gastrin","Motilin"],"a":1,"e":"Secretin and GIP are duodenal hormones released in response to acid/fat that inhibit gastric acid secretion."},
{"id":228,"s":1,"t":"Gastrointestinal Physiology","q":"Which of the following plays important role in satiety?","o":["CCK","GIP","VIP","Substance P","Glucagon"],"a":0,"e":"CCK acts on local duodenal vagal sensory nerves to signal satiety to the brain."},
{"id":229,"s":1,"t":"Gastrointestinal Physiology","q":"Which of the following statement about Gastrointestinal hormone is true?","o":["Gastrin is released as a result of stomach distension and vagal stimulation","Secretin causes excessive gastric secretion and accelerates gastric emptying","Vasoactive intestinal peptide induces gastric acid secretion","Secretin stimulates pancreatic acinar cells to secrete enzymes","The primary function of gastrin is stimulation of local nervous plexus in stomach and small intestine."],"a":0,"e":"Gastrin release from antral G cells is directly stimulated by stomach distension, vagal stimulation, and digested proteins."},
{"id":230,"s":2,"t":"Cardiovascular Physiology","q":"The neural center that controls the changes in blood vessel diameter is?","o":["Vasomotor center","Carotid center","The AV node","The cardiovascular center","The bundle of His"],"a":0,"e":"The vasomotor center (cardiac center) in the medulla oblongata and lower pons regulates blood vessel diameter via vasoconstrictor and vasodilator areas."},
{"id":231,"s":2,"t":"Cardiovascular Physiology","q":"The amount of blood in the ventricles just at the beginning of contraction is the?","o":["End diastolic volume","End Systolic Volume","Cardiac contractility deficit","Pulse deficit","Stroke volume"],"a":0,"e":"End-Diastolic Volume (EDV) is the maximum volume of blood present in each ventricle at the end of diastole, immediately before ventricular contraction begins."},
{"id":232,"s":2,"t":"Cardiovascular Physiology","q":"The following decrease cardiac output:","o":["Increased venous return","Standing upright for a long time","Pregnancy","Increased blood volume","Exercise"],"a":1,"e":"Prolonged upright standing causes gravitational pooling of blood in lower extremity capacitance vessels, reducing venous return and decreasing cardiac output. Conversely, exercise, pregnancy, and increased blood volume increase cardiac output."},
{"id":233,"s":2,"t":"Cardiovascular Physiology","q":"The type of shock that bacteria endotoxins play a huge role in is?","o":["Hypovolemic shock","Hemorrhagic shock","Neurogenic shock","Septic shock","Anaphylactic shock"],"a":3,"e":"Septic shock (septicemia) is caused by systemic bacterial infections and endotoxins, leading to widespread vasodilation and tissue hypoperfusion."},
{"id":234,"s":2,"t":"Cardiovascular Physiology","q":"Concerning ventricular systole the following is correct:","o":["Aortic and pulmonary valves close when ventricular pressure exceeds pressure in aorta and pulmonary artery.","The ventricles are a closed chamber during isovolumetric contraction and isovolumetric relaxation","End systolic volume (ESV) is about 90mls.","Ejection fraction is stroke volume divided by end systolic volume expressed as a percentage","Blood flows slowly out of the ventricles during ventricular ejection phase"],"a":1,"e":"During both isovolumetric phases, all heart valves (AV and semilunar valves) are completely closed, forming sealed ventricular chambers."},
{"id":235,"s":2,"t":"Cardiovascular Physiology","q":"In the coronary circulation the following are true except:","o":["Blood flow is directly proportional to rate of heart metabolism","Blood flow decreases during systole","All venous drainage is through the central cardiac vein","There is a large capillary reserve","Blood flow is about 5% of cardiac output"],"a":2,"e":"Coronary venous blood drains via the coronary sinus, cardiac veins, and directly into the cardiac chambers through the deep venous system (Thebesian veins)."},
{"id":236,"s":3,"t":"Renal Physiology","q":"Which of the following is primarily secreted into the proximal tubule?","o":["Sodium","Hydrogen ions","Glucose","Water","Chloride"],"a":1,"e":"In the proximal convoluted tubule, hydrogen ions (H+) are actively secreted into the lumen via Na+/H+ counter-transport, whereas sodium, glucose, water, and chloride are predominantly reabsorbed."},
{"id":237,"s":3,"t":"Renal Physiology","q":"Acidosis may result from which of the following conditions?","o":["Increased CO2 excretion","Excessive loss of bicarbonate","Hypoventilation","Hyperventilation","Both B and C"],"a":4,"e":"Acidosis can result from loss of bicarbonate (causing metabolic acidosis, as in diarrhea) or hypoventilation (causing CO2 retention and respiratory acidosis)."},
{"id":238,"s":3,"t":"Renal Physiology","q":"In the distal tubule, which of the following cells play a role in hydrogen ion secretion?","o":["Principal cells","Intercalated cells","Macula densa","Podocytes","Mesangial cells"],"a":1,"e":"Intercalated cells (I-cells) in the distal tubule and collecting duct contain active H+-ATPase proton pumps for secreting hydrogen ions into the tubular lumen."},
{"id":239,"s":3,"t":"Renal Physiology","q":"Which of the following is a key buffer system in the body?","o":["Phosphate buffer","Ammonia buffer","Bicarbonate buffer","Protein buffer","All of the above"],"a":4,"e":"Bicarbonate, phosphate, protein, and ammonia systems all serve as essential physiological buffer systems in the body."},
{"id":240,"s":3,"t":"Renal Physiology","q":"Which part of the nephron is primarily responsible for concentrating urine?","o":["Proximal tubule","Loop of Henle","Distal tubule","Collecting duct","Glomerulus"],"a":1,"e":"The Loop of Henle and vasa recta act as countercurrent multipliers and exchangers to build the hypertonic medullary gradient required for urine concentration."},
{"id":241,"s":3,"t":"Renal Physiology","q":"Which of the following conditions would lead to dilute urine?","o":["High levels of antidiuretic hormone (ADH)","Low levels of antidiuretic hormone (ADH)","Dehydration","Increased sodium reabsorption","Increased water reabsorption"],"a":1,"e":"Low levels or absence of ADH leave the collecting ducts impermeable to water, resulting in the excretion of a large volume of dilute urine."},
{"id":242,"s":3,"t":"Renal Physiology","q":"Which of the following hormones increases water reabsorption in the collecting duct?","o":["Aldosterone","Antidiuretic hormone (ADH)","Renin","Atrial natriuretic peptide","Cortisol"],"a":1,"e":"ADH binds to receptors on principal cells in the collecting tubule, inserting aquaporin-2 water channels to increase water reabsorption."},
{"id":243,"s":3,"t":"Renal Physiology","q":"Which hormone is released by the kidneys in response to low blood pressure?","o":["Renin","Aldosterone","Antidiuretic hormone (ADH)","Atrial natriuretic peptide (ANP)","Cortisol"],"a":0,"e":"Juxtaglomerular cells in renal afferent arterioles secrete renin in response to decreased renal perfusion pressure or low ECF volume."},
{"id":244,"s":3,"t":"Renal Physiology","q":"Osmolarity of a solution refers to:","o":["The amount of water in the body","The number of solute particles per liter of solvent","The number of solute particles per liter of solution","The total weight of body fluids","The amount of water out of the body"],"a":2,"e":"Osmolarity is defined as the number of solute particles (osmoles) per liter of solution."},
{"id":245,"s":1,"t":"Gastrointestinal Physiology","q":"Gastrin and HCl inhibition is triggered by which of the following hormones?","o":["Histamine","Noradrenaline","Acetylcholine","Secretin","CCK"],"a":3,"e":"Secretin is released from duodenal S cells in response to acidic chyme and acts to inhibit gastric acid secretion and gastrin release."},
{"id":246,"s":1,"t":"Gastrointestinal Physiology","q":"Gastric juice secretion is decreased by:","o":["Vagal inhibition","Noradrenaline","Bowel wall distension","Ingestion of protein","Serotnine"],"a":0,"e":"Vagal nervous stimulation strongly excites gastric juice and pepsinogen production; thus, vagal inhibition or vagotomy decreases gastric acid secretion."},
{"id":247,"s":1,"t":"Gastrointestinal Physiology","q":"Symptoms of chronic pancreatitis include all of the following except:","o":["Constipation","Diabetes","Diarrhea","Weight loss","Abdominal pain"],"a":0,"e":"Chronic pancreatitis causes malabsorption of nutrients leading to severe diarrhea (steatorrhea), diabetes, weight loss, and abdominal pain."},
{"id":248,"s":1,"t":"Gastrointestinal Physiology","q":"The main complication of diarrhea is:","o":["Metabolic alkalosis","Edema","Loss of consciousness","Dehydration","Hypervolaemia"],"a":3,"e":"Rapid loss of water and electrolytes in diarrheal fluid leads to dehydration and potential circulatory shock."},
{"id":249,"s":1,"t":"Gastrointestinal Physiology","q":"Leptin is a polypeptide hormone secreted by which of the following?","o":["Pituitary.","F-cells of the pancreatic islets of Langerhans.","Stomach.","Adipose tissue","Ileum"],"a":3,"e":"Leptin is a polypeptide hormone produced by adipose tissue (fat cells) that regulates energy balance and satiety in the brain."},
{"id":250,"s":1,"t":"Gastrointestinal Physiology","q":"What is the role of bile in fat digestion?","o":["To break down fats into fatty acids","To emulsify fats and increase surface area for lipase action","To activate lipase","To neutralize stomach acid","To absorb fatty acids into the bloodstream"],"a":1,"e":"Bile salts reduce surface tension and emulsify large fat globules into minute droplets, increasing the surface area for pancreatic lipase action."},
{"id":251,"s":1,"t":"Gastrointestinal Physiology","q":"What is the main carbohydrate absorbed into the bloodstream after digestion?","o":["Fructose","Lactose","Maltose","Glucose","Starch"],"a":3,"e":"Carbohydrates are absorbed almost entirely as monosaccharides, with glucose accounting for over 80% of absorbed sugars."},
{"id":252,"s":1,"t":"Gastrointestinal Physiology","q":"Which enzyme is responsible for breaking down starch into maltose in the mouth?","o":["Amylase","Lactase","Sucrase","Pepsin","Maltase"],"a":0,"e":"Salivary alpha-amylase (ptyalin) initiates starch digestion in the mouth, converting complex starches into maltose and short polymers."},
{"id":253,"s":1,"t":"Gastrointestinal Physiology","q":"The hormone directly responsible for the secretion of pancreatic ductile HCO3- is:","o":["Secretin","VIP","Somatostatin","Substance P","CCK"],"a":0,"e":"Secretin acts on pancreatic ductal epithelial cells to stimulate copious secretion of a sodium bicarbonate-rich fluid."},
];

